/**
 * Lightweight web worker pool manager.
 *
 * A small, dependency-free pool that supports:
 * - reusing idle workers,
 * - growing the pool up to `maxSize`,
 * - optional task queuing when the pool is saturated,
 * - and terminating idle workers after `idleTimeout`.
 *
 * Additionally, the pool emits a synthetic `pool:idle` message when the
 * pool transitions to fully idle (no active tasks and an empty queue).
 * This allows consumers to react when all asynchronous work has completed.
 *
 *
 */
import { o2u8, u82o } from './powerBuffer.js';
import { abortReason } from '../utils/abort.js';
import { isError } from '../utils/errors.js';
import WorkerAgnostic from './WorkerAgnostic.js';
import { nowMs } from '../utils/now.js';
import { attach, detach } from './metrics.js';
import { setSafeInterval } from '../utils/timers.js';
import { PowerQueue } from './powerQueue.js';
import { PowerLogger } from './powerLogger.js';
import { PowerEventBus } from './powerEventBus.js';
import { PowerServo } from './powerServo.js';
import {
  frameEncodedJson,
  decodeMessage,
  encodeMessage,
  isRawPayload,
  isNativeEnvelope,
  isCapabilityAnnouncement,
  encodeNativeEnvelope,
  collectTransferables,
  encodeNative,
  canUseNativeClone,
  MESSAGE_CODECS,
} from './powerMessageCodec.js';
import {
  DEFAULT_HARDWARE_CONCURRENCY,
  DEFAULT_POOL_SIZE,
  DEFAULT_REAPER_MIN_INTERVAL_MS,
  DEFAULT_IDEMPOTENCY_SWEEP_BATCH,
  ENCODE_CACHE_LARGE_KEY_LENGTH,
  DEFAULT_MAX_DRAIN_WAITERS,
  DEFAULT_POOL_IDLE_TIMEOUT_MS,
  DEFAULT_TIMEOUT_MS,
  DEFAULT_AUTOSCALE_MIN_INTERVAL_MS,
  DEFAULT_AUTOSCALE_INTERVAL_MS,
  DEFAULT_AUTOSCALE_COOLDOWN_MS,
  DEFAULT_AUTOSCALE_BACKOFF_MAX_MULTIPLIER,
  DEFAULT_AUTOSCALE_LONG_WINDOW_ALPHA,
  DEFAULT_AUTOSCALE_AIMD_BETA,
} from './constants.js';
import { assertLimitRequired, assertKnownOptions } from '../utils/options.js';
import { markUntransferable } from '../utils/transferable.js';

/** @typedef {import('./jsdoc-types.js').WorkerLike} WorkerLike */

// Process-unique prefix for generated correlation ids, computed once per
// process rather than once per message. See `_generateCorrelationId` for why
// the counter alone is not enough. 2^32 is enough entropy that two processes
// colliding is not a practical concern, and it is drawn once, so the cost does
// not appear on the hot path.
const CORRELATION_PROCESS_TAG = Math.floor(Math.random() * 0xffffffff).toString(36);

// Process-global, not per pool. A per-pool counter with a shared tag is not
// unique across pools in the same process - two pools both emit `<tag>-0` -
// which is exactly the collision the tag was supposed to prevent. Caught by
// test/powerPool.correlation.test.js before it shipped.
let _correlationSequence = 0;

// Module-level tuning constants (imported from shared constants.js)

/**
 * Build a coded `Error` for a pool-side refusal.
 *
 * The pool signals "your work was refused" through three distinct codes rather
 * than one generic failure, because the caller's correct response differs in
 * each case: retry later (`ERR_POOL_DRAIN_TIMEOUT`), stop draining
 * (`ERR_POOL_DRAIN_TOO_MANY_WAITERS`), or shed load
 * (`ERR_POOL_QUEUE_FULL`). A single `Error` message forces the caller to
 * string-match to tell them apart.
 *
 * @param {string} code - The `err.code` to set.
 * @param {string} message - Human-readable detail.
 * @returns {Error & {code: string}}
 * @private
 */
function poolRefusal(code, message) {
  const err = /** @type {Error & {code: string}} */ (new Error(message));
  err.code = code;
  return err;
}

/** @typedef {import('./jsdoc-types.js').TransferList} TransferList */

/**
 * A message on its way to a worker, after preparation but before it is posted.
 *
 * `deferred` is the load-bearing member, and it is what the batch path was
 * missing. `true` means the encode was **deliberately not done** and the framing
 * is still owed, so the dispatch site must frame before posting. It is set when
 * the encode cannot safely be shared — an object message under `messageCodec:
 * 'negotiated'`, where the carrier is a per-worker decision, or under
 * `prepareBuffers`' default `clone: false`, where a cached body cannot be both
 * shared and correct on the wire.
 *
 * Posting a `deferred` item verbatim is a protocol error, not a slow path: the
 * worker reads the first byte of raw JSON — `{`, or 123 — as a protocol version
 * and rejects the message. Every dispatch site therefore has to check this, which
 * is why the member is on the type rather than being a local variable at each
 * one.
 *
 * @typedef {object} PreparedItem
 * @property {*} message - The value to post. A `Uint8Array` under a framing codec,
 *   the original object when `deferred`.
 * @property {TransferList|undefined} transfer - Must be `undefined` whenever
 *   `message` is a shared buffer: a transfer list detaches its entries, and a
 *   detached cache entry is the bug `clone` exists to avoid.
 * @property {boolean} [deferred] - Framing is still owed; see above.
 * @property {number} [priority] - Task priority for queue ordering. Higher values
 *   are dispatched before lower values when the pool is saturated. Defaults to `0`
 *   when absent.
 */

/**
 * Are every entry in a transfer list still live?
 *
 * A successful `postMessage` *detaches* everything in its transfer list - that
 * is the whole point, and it is what makes zero-copy possible. A `postMessage`
 * that **throws** may already have detached some or all of it, because the
 * structured clone runs before the failure is detected. There is no API to
 * learn which, only which are already gone, so the only safe read is "is
 * anything already detached".
 *
 * `ArrayBuffer.prototype.detached` is the precise test and is available in every
 * runtime this library targets (Node >= 22.12 and every current browser), so it
 * is the only one used. The older `byteLength === 0` heuristic is deliberately
 * *not* used alongside it: a legitimately zero-length buffer is a perfectly
 * valid transferable, and treating it as dead would refuse real work.
 *
 * @param {TransferList} transfer - The transfer list to inspect.
 * @returns {boolean} `true` when nothing in the list is detached.
 * @private
 */
function isTransferListLive(transfer) {
  if (!Array.isArray(transfer)) return true;
  for (let i = 0; i < transfer.length; i++) {
    const item = transfer[i];
    if (item instanceof ArrayBuffer) {
      if (isDetached(item)) return false;
    } else if (ArrayBuffer.isView(item)) {
      if (isDetached(item.buffer)) return false;
    } else if (item === null || typeof item !== 'object') {
      // Not a transferable at all. Posting with it is guaranteed to throw, and
      // the point of this check is to fail *before* the post, not after.
      return false;
    }
  }
  return true;
}

/**
 * Read `ArrayBuffer.prototype.detached` without requiring the `es2024` lib.
 *
 * The getter is ES2024, and this library's `lib` target predates it. The
 * property is read through a cast rather than by raising the target, because
 * raising it would change the meaning of every other check in the project
 * rather than this one. A runtime without the getter reports `undefined`,
 * which compares `!== true` and is correctly treated as "not known to be
 * detached" - the pre-check then simply does not fire, which is the same
 * behaviour as before this check existed.
 *
 * @param {ArrayBuffer|ArrayBufferLike|undefined|null} buffer
 * @returns {boolean}
 * @private
 */
function isDetached(buffer) {
  return /** @type {{detached?: boolean}|null|undefined} */ (buffer)?.detached === true;
}

// Lightweight stable-shape wrapper for underlying worker-like objects.
// Extracted to module-level to avoid recreating the class on every
// `_addWorkerInstance()` call which reduces per-worker allocation cost
// and improves hidden-class stability in V8.
class WorkerWrapper {
  /**
   * @param {WorkerLike} _underlying - The worker this wrapper forwards to.
   * @param {import('./powerLogger.js').PowerLogger} _logger
   * @param {PowerPool} _pool
   */
  constructor(_underlying, _logger, _pool) {
    this._underlying = _underlying;
    this._logger = _logger;
    this._pool = _pool;
    /** @type {?(function(...*):void)} */
    this.onmessage = null;
    /** @type {?(function(...*):void)} */
    this.onerror = null;
    /** @type {?(function(...*):void)} */
    this.onmessageerror = null;
  }

  /**
   * @param {*} message
   * @param {TransferList} [transfer] - Transferable
   *   list, or an iterable/array-like of one. `undefined` means "no transfer".
   * @returns {*}
   */
  postMessage(message, transfer) {
    let msg = message;
    let tr = transfer;
    const isTransferable =
      msg instanceof Uint8Array || ArrayBuffer.isView(msg) || msg instanceof ArrayBuffer;
    if (isTransferable) {
      if (Array.isArray(tr)) {
        try {
          if (tr.length) this._underlying.postMessage(msg, tr);
          else this._underlying.postMessage(msg);
          return;
        } catch (err) {
          this._logger.error(err, 'Failed to postMessage to underlying worker');
          throw err;
        }
      }

      if (!tr) {
        const buffer = msg instanceof ArrayBuffer ? msg : msg.buffer;
        if (buffer?.byteLength > 0) tr = [buffer];
      }

      try {
        if (tr?.length) this._underlying.postMessage(msg, tr);
        else this._underlying.postMessage(msg);
      } catch (err) {
        this._logger.error(err, 'Failed to postMessage to underlying worker');
        throw err;
      }
      return;
    }

    const isPlainObject =
      msg !== null &&
      typeof msg === 'object' &&
      !ArrayBuffer.isView(msg) &&
      !(msg instanceof ArrayBuffer);
    // A native envelope is *already* in wire form. Re-encoding it to JSON bytes
    // would post a bare body that reads as a legacy message: a worker using
    // `decodeInbound` would take its legacy branch, parse the bytes, and hand
    // the task code the envelope instead of the payload — a silent failure with
    // no error anywhere, which is the worst shape a protocol bug can take.
    if (isPlainObject && !isNativeEnvelope(msg)) {
      try {
        const u8 = this._pool._encodeForTransfer(message);
        // Clone the encoded bytes before transferring. `_encodeForTransfer`
        // may return a cached Uint8Array; transferring its buffer would detach
        // (neuter) the cached instance, corrupting later cache hits. Slicing
        // mirrors the safe handling in `_prepareForTransfer`.
        const buf = u8.slice();
        // Efficiently ensure the encoded buffer is included in the transfer list
        if (!tr) {
          tr = [buf.buffer];
        } else if (Array.isArray(tr)) {
          if (!tr.includes(buf.buffer)) tr.push(buf.buffer);
        } else {
          // For array-like or other iterable transfer lists, convert once
          const arr = Array.from(tr);
          if (!arr.includes(buf.buffer)) arr.push(buf.buffer);
          tr = arr;
        }
        msg = buf;
      } catch (err) {
        tr = transfer;
        msg = message;
      }
    }

    try {
      if (tr?.length) this._underlying.postMessage(msg, tr);
      else this._underlying.postMessage(msg);
    } catch (err) {
      this._logger.error(err, 'Failed to postMessage to underlying worker');
      throw err;
    }
  }

  addEventListener(...args) {
    return this._underlying.addEventListener(...args);
  }

  removeEventListener(...args) {
    return this._underlying.removeEventListener(...args);
  }

  terminate() {
    if (typeof this._underlying.terminate === 'function') this._underlying.terminate();
  }
}

/**
 * PowerPoolShutdownError
 *
 * Error thrown when the `PowerPool` is shut down and pending tasks are rejected.
 *
 * Carries `code === 'ERR_POOL_TERMINATED'`, the same code the pool uses for the
 * synchronous throw from a dispatch method on a shut-down pool. Both mean the
 * same thing — the pool is finished, so is the work — and `guides/errors.md`
 * tells callers to branch on `err.code`. Without it, a caller awaiting a
 * response at shutdown got an error with no code and fell through the
 * documented `switch` to `default`, which is the case most likely to be hit:
 * shutting down is exactly when pending promises are still outstanding.
 * `name` is unchanged, so `err.name === 'PowerPoolShutdownError'` keeps
 * working.
 *
 * @class PowerPoolShutdownError
 * @extends {Error}
 * @public
 */
export class PowerPoolShutdownError extends Error {
  constructor(message = 'PowerPool has been shut down') {
    super(message);
    this.name = 'PowerPoolShutdownError';
    this.code = 'ERR_POOL_TERMINATED';
  }
}

/**
 * @typedef {import('./jsdoc-types.js').WorkerObj} WorkerObj
 */

/**
 * PostMessage and pending-response typedefs are defined centrally to avoid
 * duplication across multiple helper modules. Import aliases are used here
 * so typedoc and editors can resolve the shape while keeping local docs
 * concise.
 * @typedef {import('./jsdoc-types.js').PostMessageOptions} PostMessageOptions
 */

/**
 * @typedef {import('./jsdoc-types.js').PendingResponseEntry} PendingResponseEntry
 */

/**
 * @typedef {import('./jsdoc-types.js').PowerPoolOptions} PowerPoolOptions
 */

/**
 * Manager for a pool of web workers.
 *
 * @example
 * import MinionWorker from './worker.js?worker&inline'
 * const pool = new PowerPool(MinionWorker, { size: 4, idleTimeout: 30000 });
 * pool.onmessage = (e) => { logger.log(e.data); };
 * pool.postMessage({ payload: {} });
 *
 * @example <caption>Explicit Resource Management (Node >= 22.12 / modern browsers)</caption>
 * // `Symbol.dispose` runs synchronously, so `using` hard-stops the pool at
 * // scope exit. Prefer `await using` to drain in-flight work first.
 * import MinionWorker from './worker.js?worker&inline'
 * {
 *   using pool = new PowerPool(MinionWorker, { size: 4 });
 *   await pool.postMessage({ payload: {} }, undefined, { awaitResponse: true });
 * } // pool.shutdown() is called here, synchronously
 *
 * // To drain pending tasks before terminating:
 * {
 *   await using pool = new PowerPool(MinionWorker, { size: 4 });
 *   await pool.postMessage({ payload: {} }, undefined, { awaitResponse: true });
 * } // pool[Symbol.asyncDispose]() drains then terminates
 */
/**
 * PowerPool
 *
 * Manager for a pool of worker-like objects providing task dispatch, queuing,
 * autoscaling, and lifecycle management. See constructor docs for options.
 *
 * @class PowerPool
 * @public
 */
export class PowerPool {
  /**
   * Create a PowerPool.
   *
   * @param {Function|string} workerSource - A Worker constructor, a worker factory, or a relative path string. If the provided function is not constructable, it is invoked directly; if a string path is provided, the pool attempts to resolve it via `new URL(path, import.meta.url)` before falling back to a plain `Worker(path)`.
   * @param {PowerPoolOptions=} options
   * @param {number} [options.size] - Initial number of workers to create.
   * @param {number} [options.minSize=1] - Minimum number of workers to keep alive.
   * @param {number} [options.maxSize] - Maximum number of workers allowed in the pool. The pool coerces this value to be at least `minSize`.
   * @param {Object} [options.workerOptions] - Options forwarded to the Worker constructor when using a string path.
   * @param {number} [options.maxTasksPerWorker=Infinity] - Soft capacity per worker before considering it busy.
   * @param {number} [options.idleTimeout=60000] - Milliseconds after which idle workers (beyond `minSize`) will be terminated.
   * @param {boolean} [options.taskQueue=true] - Whether to queue tasks when all workers are busy.
   * @param {'enqueue'|'drop-oldest'|'drop-newest'|'reject'} [options.queuePolicy='enqueue'] - Queue overflow behavior when the pool is saturated.
   * @param {boolean} [options.lazy=true] - If true, defer creating workers up to `size` until demand; only `minSize` workers are created at construction.
   * @param {number} [options.slowTaskThreshold=Infinity] - Task duration (ms) above which a completed task is counted as "slow". When finite, `stats().performance.percentSlowTasks` reports the exact percentage of tasks exceeding this threshold. Defaults to `Infinity` (disabled; `percentSlowTasks` stays `0`).
   * @param {number} [options.maxQueueLength=Infinity] - Hard cap on queued tasks. With the default `queuePolicy: 'enqueue'` and no cap, a saturated pool grows its queue until the process runs out of memory; a cap makes the overflow observable instead - the incoming task is refused (`false`, or `ERR_POOL_QUEUE_FULL` when awaiting a response). `drop-oldest` still evicts the oldest to make room.
   * @param {number} [options.maxDrainWaiters=100] - Cap on concurrent `drain()` waits, so a caller that drains in a loop cannot accumulate unbounded `idle` listeners. (Internally `DEFAULT_MAX_DRAIN_WAITERS`; not exported.)
   */
  constructor(workerSource, options = {}) {
    assertKnownOptions(
      options,
      [
        'size',
        'minSize',
        'maxSize',
        'workerOptions',
        'maxTasksPerWorker',
        'idleTimeout',
        'taskQueue',
        'queuePolicy',
        'lazy',
        'debugLevel',
        'listenerMaxListeners',
        'weakListeners',
        'queueHighThreshold',
        'maxQueueLength',
        'observability',
        'maxDrainWaiters',
        'autoScale',
        'awaitResponseTimeout',
        'slowTaskThreshold',
        'maxListeners',
        'messageCodec',
        'encodeCacheLimit',
        'encodeCacheByteLimit',
        'idempotencyTtlMs',
        'priority',
        'priorityAgingMs',
      ],
      'PowerPool'
    );
    // A default parameter only covers `undefined`, so `new PowerPool(W, null)`
    // reached the destructuring below with `null` and threw
    // `TypeError: Cannot read properties of null (reading 'size')` - naming an
    // internal field rather than the argument the caller got wrong. The options
    // guard further down explicitly exempts `null` (`arguments[1] != null`),
    // which is the intent; it just never got the chance to run, because the
    // destructuring happens first. Normalise here so the guard means what it
    // says.
    if (options === null) options = {};
    const hwConcurrency =
      (typeof navigator !== 'undefined' && navigator.hardwareConcurrency) ||
      DEFAULT_HARDWARE_CONCURRENCY;
    const {
      size = Math.min(hwConcurrency, DEFAULT_POOL_SIZE),
      minSize = DEFAULT_POOL_SIZE,
      maxSize = Math.max(size, hwConcurrency),
      workerOptions = {},
      maxTasksPerWorker: maxTasksPerWorkerOption,
      idleTimeout = DEFAULT_POOL_IDLE_TIMEOUT_MS,
      taskQueue = true,
      queuePolicy = 'enqueue',
      lazy = true,
      // default timeout (ms) applied to awaitResponse Promises when callers omit per-call timeout
      awaitResponseTimeout = DEFAULT_TIMEOUT_MS,
      slowTaskThreshold = Infinity,
      autoScale = false,
      priorityAgingMs = 0,
    } = options;
    if (!Number.isFinite(priorityAgingMs) || priorityAgingMs < 0) {
      throw new RangeError('PowerPool: `priorityAgingMs` must be finite and >= 0');
    }
    this._priorityAgingMs = priorityAgingMs;
    const maxTasksPerWorker =
      maxTasksPerWorkerOption === undefined && autoScale
        ? 1
        : (maxTasksPerWorkerOption ?? Infinity);

    // Validate workerSource early to fail fast on incorrect usage.
    if (typeof workerSource !== 'function' && typeof workerSource !== 'string') {
      throw new TypeError('PowerPool workerSource must be a function or string');
    }

    this._workerSource = workerSource;
    this._workerOptions = workerOptions;
    // These were `Math.max(0, value)`, which is silent about the one input
    // that matters: a non-numeric value makes the result NaN, and **every
    // comparison against NaN is false**. So `minSize: 'lots'` did not produce a
    // pool that complained - it produced a pool whose reaper considered every
    // worker non-idle, or rather whose idle comparison could never be true, and
    // which therefore never terminated anything while reporting a worker count
    // of NaN. `Math.max(0, …)` is the wrong tool for clamping a value you have
    // not checked is a number.
    //
    // Zero stays legal for every size option, because "start with no workers and
    // scale up on demand" is a real configuration, and clamping it to 1 would
    // take that option away. Negative and non-numeric values are the mistakes.
    // `maxTasksPerWorker` is deliberately left unvalidated. `0` is meaningful
    // here in a way it is not for the size options: it means "every worker is
    // immediately full", which is how several existing tests force a post down
    // the queue path. Constraining it to >= 1 would change documented behaviour
    // to tidy up a coercion that is not actually harmful - `0` is finite, so it
    // never produces the NaN this section is about.
    this._maxTasksPerWorker = maxTasksPerWorker;
    this.minSize = assertLimitRequired(minSize, {
      name: 'minSize',
      className: 'PowerPool',
      integer: true,
      min: 0,
      fallback: DEFAULT_POOL_SIZE,
    });
    this.maxSize = Math.max(
      this.minSize,
      assertLimitRequired(maxSize, {
        name: 'maxSize',
        className: 'PowerPool',
        integer: true,
        min: 0,
        fallback: this.minSize,
      })
    );
    this.idleTimeout = assertLimitRequired(idleTimeout, {
      name: 'idleTimeout',
      className: 'PowerPool',
      min: 0,
      allowInfinity: true,
      fallback: DEFAULT_POOL_IDLE_TIMEOUT_MS,
    });
    this.taskQueueEnabled = Boolean(taskQueue);
    this._queuePolicy = ['enqueue', 'drop-oldest', 'drop-newest', 'reject'].includes(queuePolicy)
      ? queuePolicy
      : 'enqueue';
    // Hard cap on the task queue. `Infinity` (the default) preserves the
    // pre-2.0 behaviour where `queuePolicy: 'enqueue'` grows without bound.
    this._maxQueueLength = assertLimitRequired(options.maxQueueLength, {
      name: 'maxQueueLength',
      className: 'PowerPool',
      integer: true,
      min: 0,
      allowInfinity: true,
      fallback: Infinity,
    });
    this._maxDrainWaiters = assertLimitRequired(options.maxDrainWaiters, {
      name: 'maxDrainWaiters',
      className: 'PowerPool',
      integer: true,
      min: 1,
      fallback: DEFAULT_MAX_DRAIN_WAITERS,
    });
    /**
     * Number of `drain()` calls currently *waiting* for idle. Each one holds an
     * `idle` listener, so this is the bound that keeps a caller draining in a
     * loop from accumulating listeners without limit. See
     * `DEFAULT_MAX_DRAIN_WAITERS`.
     * @type {number}
     */
    this._drainWaiters = 0;

    // performance tracking
    this._createdAt = nowMs(); // pool creation timestamp (ms)
    this._totalWorkersCreated = 0; // increments for every created worker instance
    this._totalTasksCompleted = 0; // increments for every finished task
    // Batched posts that could not be dispatched. `postMessageBatch` reports a
    // per-item boolean, so a failure used to be a `false` in an array and
    // nothing else — no log, no event, no count — which is the one failure mode a
    // caller cannot tell from "the worker was busy".
    this._postFailures = 0;
    // Welford streaming statistics for O(1) memory: count, mean, M2 (for variance)
    this._taskDurationsWelfordCount = 0;
    this._taskDurationsWelfordMean = 0;
    this._taskDurationsWelfordM2 = 0;
    this._taskDurationsMin = Number.POSITIVE_INFINITY;
    this._taskDurationsMax = Number.NEGATIVE_INFINITY;
    this._queueWaitWelfordCount = 0;
    this._queueWaitWelfordMean = 0;
    this._queueWaitWelfordM2 = 0;
    this._queueWaitMin = Number.POSITIVE_INFINITY;
    this._queueWaitMax = Number.NEGATIVE_INFINITY;
    // Threshold (ms) above which a completed task is counted as "slow".
    // `Infinity` disables slow-task counting so `percentSlowTasks` stays 0.
    this._slowTaskThreshold = Number.isFinite(slowTaskThreshold)
      ? Number(slowTaskThreshold)
      : Infinity;
    this._slowTaskCount = 0;
    // optional autoscaling configuration (disabled by default)
    this._ewmaLatency = null; // pool-level EWMA for recent task latency (ms)
    this._autoScale = null; // { enabled, intervalMs, targetMs, alpha, cooldownMs, hysteresis }
    this._autoScaleInterval = null;
    this._lastAutoScaleAt = 0; // timestamp (ms) of last scale action (0=never)
    this._lastAutoScaleReason = null;
    this._lastAutoScaleOutcome = null;
    // running aggregate for terminated workers: total completed tasks and count
    this._terminatedWorkerTaskCountsTotal = 0;
    this._terminatedWorkerTaskCountsCount = 0;

    /** @type {WorkerObj[]} */
    this.workers = [];
    this.queue = new PowerQueue();
    const busOptions = {
      maxListeners: options?.listenerMaxListeners ?? options?.maxListeners,
      weak: Boolean(options?.weakListeners),
    };
    this._bus = new PowerEventBus(busOptions);
    // optional queue high-watermark threshold for emitting backpressure events
    this._queueHighThreshold = Number.isFinite(Number(options?.queueHighThreshold))
      ? Math.max(0, Math.floor(Number(options?.queueHighThreshold)))
      : Infinity;
    this._queueHighCrossed = false; // track current high state to avoid event spam
    this._onmessage = null;
    this._onerror = null;
    this._onidle = null;
    this._onresize = null;
    this._nextIndex = 0;
    // monotonic id allocator for workers to ensure ids remain unique
    this._nextWorkerId = 0;
    // monotonic per-pool correlation counter appended to generated ids
    /** number of currently active (dispatched) tasks across all workers */
    this._activeTasks = 0;
    /** whether the pool is considered idle (no active tasks and empty queue) */
    this._isIdle = true;
    /** whether queued dispatch is paused */
    this._queuePaused = false;
    /**
     * Wire protocol for object messages.
     *
     * - `'framed'` (**default since 2.0**) posts a `PowerMessageCodec`
     *   envelope: `[version][codec][length][payload]`. Workers read
     *   `decodeMessage(e.data).value` instead of `u82o(e.data)`, binary frames
     *   survive intact, and the version byte lets the protocol evolve without
     *   another flag day.
     * - `'legacy'` restores the 1.x behaviour: a bare `Uint8Array` of JSON,
     *   sniffed on the way back in. Provided so a worker can be migrated on its
     *   own schedule. See the migration note in guides/powerPool.md.
     * - `'negotiated'` starts out identical to `'framed'` and upgrades **per
     *   worker**: a worker that advertises the native carrier with
     *   `announceCapabilities()` is sent the structured-clone carrier instead,
     *   which preserves `Map`, `Set`, `Date`, `BigInt` and cycles that the JSON
     *   frame silently destroys. Workers that do not advertise keep getting the
     *   frame, so a pool can be switched on before any worker is ready.
     *
     * @type {'framed'|'legacy'|'negotiated'}
     */
    this._messageCodec = MESSAGE_CODECS.has(options.messageCodec) ? options.messageCodec : 'framed';
    /**
     * Whether this runtime can structured-clone at all. Checked once here so
     * `'negotiated'` on a runtime without `structuredClone` degrades to the
     * framed path rather than throwing per message.
     */
    this._nativeCloneAvailable = canUseNativeClone();
    /**
     * Terminal flag. Set by `shutdown()` / `terminate()`; once true the pool
     * refuses to dispatch, enqueue or grow, so a late `postMessage()` cannot
     * resurrect it (which previously created a worker with no reaper
     * interval, pinning the Node.js process).
     * @type {boolean}
     */
    this._terminated = false;

    // Create a per-instance logger. Allow callers to override via options.debugLevel (default 1).
    const dbg = typeof options?.debugLevel === 'number' ? options.debugLevel : 1;
    this._logger = new PowerLogger(dbg, { name: 'powerPool' });
    // Basic options validation: when an explicit options argument is provided it must be an object
    if (arguments.length > 1 && arguments[1] != null && typeof arguments[1] !== 'object') {
      throw new TypeError('PowerPool options must be an object');
    }
    // correlation map for Promise-style postMessage responses
    this._pendingResponses = new Map(); // correlationId -> { resolve, reject, timer }
    // map underlying worker -> WorkerObj for shared handler dispatch
    this._underlyingToWorkerObj = new Map();

    // pool-level default awaitResponse timeout (ms). `0` means disabled.
    this._defaultAwaitResponseTimeout = Number.isFinite(Number(awaitResponseTimeout))
      ? Math.max(0, Math.floor(Number(awaitResponseTimeout)))
      : DEFAULT_TIMEOUT_MS;

    // When `lazy` is truthy only create `minSize` workers now and allow the
    // pool to grow on demand when tasks are posted. Default is `true`.
    const initial = lazy
      ? Math.min(this.minSize, this.maxSize)
      : Math.min(Math.max(size, this.minSize), this.maxSize);
    for (let i = 0; i < initial; i++) {
      try {
        this._addWorkerInstance();
      } catch (err) {
        // If the error signals an invalid workerSource type, rethrow so
        // callers (and tests) can observe the contract violation. Reading
        // `.message` can itself throw for a hostile object; letting that
        // propagate is the honest outcome, since we cannot classify the error.
        const msg = typeof err?.message === 'string' ? err.message : '';
        if (msg.includes('Invalid workerSource')) throw err;
        try {
          this._logger.error(err, 'Initial worker creation failed');
        } catch (e) {
          this._debugLog?.(e, 'Initial worker creation: logger error');
        }
        try {
          this._bus.emit('pool:error', { phase: 'init', error: err });
        } catch (e) {
          this._debugLog?.(e, 'Initial worker creation: bus.emit failed');
        }
        break;
      }
    }

    // reaper checks periodically and terminates idle workers
    this._reaperInterval = setSafeInterval(
      () => this._reapIdleWorkers(),
      Math.max(DEFAULT_REAPER_MIN_INTERVAL_MS, Math.floor(this.idleTimeout / 2))
    );
    // no Node `crypto` import: prefer Web Crypto APIs where available
    // small LRU-like cache for encoded messages (keyed by JSON string)
    // stores recent serialized messages to avoid re-encoding identical messages
    this._encodeCache = new Map();
    this._encodeCacheLimit = Math.max(
      16,
      options?.encodeCacheLimit ? options.encodeCacheLimit : 64
    );
    // Optional byte-size limit for the encode cache. When provided the cache
    // will evict oldest entries until the total cached bytes fit within this
    // limit. Default is `Infinity` (disabled) to preserve existing behavior.
    this._encodeCacheByteLimit = Number.isFinite(Number(options?.encodeCacheByteLimit))
      ? Math.max(0, Number(options?.encodeCacheByteLimit))
      : Infinity;
    // Running total of bytes stored in `_encodeCache` (Uint8Array.byteLength)
    this._encodeCacheBytes = 0;

    // POOL-013 — the idempotency ledger, opt-in.
    //
    // `null` means off, and off must cost *nothing*: no Map, no allocation, and no
    // branch that a caller who never asked for the feature is paying for. That is
    // why this is a TTL rather than a boolean. A boolean `idempotency: true` would
    // need a default retention window invented for it, and the row is explicit that
    // the terminal state has to be a TTL like every other piece of state here —
    // a ledger that outlives its process is a leak. `0` therefore means off, and a
    // caller who wants the ledger has to say how long a settled key is remembered.
    const idempotencyTtl = Number(options?.idempotencyTtlMs);
    this._idempotencyTtlMs =
      Number.isFinite(idempotencyTtl) && idempotencyTtl > 0 ? idempotencyTtl : 0;
    this._idempotency = this._idempotencyTtlMs > 0 ? new Map() : null;
    // Counters. `lookups` is the one the row asks for — it is the cost, and it is
    // the number that has to be zero when the feature is off.
    this._idempotencyLookups = 0;
    this._idempotencyDuplicatesInFlight = 0;
    this._idempotencyDuplicatesSettled = 0;
    this._idempotencyExpired = 0;
    this._idempotencySize = 0;

    // configure optional autoscaling
    if (options?.autoScale) {
      const as = typeof options.autoScale === 'object' ? options.autoScale : {};
      const intervalMs = Number.isFinite(Number(as.intervalMs))
        ? Math.max(DEFAULT_AUTOSCALE_MIN_INTERVAL_MS, Math.floor(as.intervalMs))
        : DEFAULT_AUTOSCALE_INTERVAL_MS;
      const targetMs = Number.isFinite(Number(as.targetMs)) ? Math.max(1, Number(as.targetMs)) : 50;
      const alpha = Number.isFinite(Number(as.alpha))
        ? Math.max(0, Math.min(1, Number(as.alpha)))
        : 0.2;
      const cooldownMs = Number.isFinite(Number(as.cooldownMs))
        ? Math.max(0, Math.floor(as.cooldownMs))
        : DEFAULT_AUTOSCALE_COOLDOWN_MS;
      const hysteresis = Number.isFinite(Number(as.hysteresis))
        ? Math.max(0, Math.min(1, Number(as.hysteresis)))
        : 0.2;
      // stepUp/stepDown: allow multi-step scaling per tick (default 1)
      const stepUp = Number.isFinite(Number(as.stepUp))
        ? Math.max(1, Math.floor(Number(as.stepUp)))
        : 1;
      const stepDown = Number.isFinite(Number(as.stepDown))
        ? Math.max(1, Math.floor(Number(as.stepDown)))
        : 1;
      // backoff controls multiplicative increase of cooldown after successive scale actions
      const backoffFactor = Number.isFinite(Number(as.backoffFactor))
        ? Math.max(1, Number(as.backoffFactor))
        : 1;
      const backoffMaxMultiplier = Number.isFinite(Number(as.backoffMaxMultiplier))
        ? Math.max(1, Number(as.backoffMaxMultiplier))
        : DEFAULT_AUTOSCALE_BACKOFF_MAX_MULTIPLIER;
      // time (ms) since last scale after which backoff multiplier is reset to 1
      const backoffResetMs = Number.isFinite(Number(as.backoffResetMs))
        ? Math.max(0, Math.floor(Number(as.backoffResetMs)))
        : cooldownMs * 4;

      // Which controller drives the adaptive concurrency limit.
      //   'ewma'      - the original target-latency heuristic (default, unchanged)
      //   'aimd'      - additive increase, multiplicative decrease
      //   'vegas'     - Vegas: infer bottleneck queue from min vs current RTT
      //   'gradient2' - Netflix Gradient2: long/short RTT EWMA divergence
      // See `_updateAdaptiveLimit` and ADR 0005 for why each controller uses a
      // *delay* signal here; non-EWMA policies also gate new admissions.
      const AUTOSCALE_POLICIES = ['ewma', 'aimd', 'vegas', 'gradient2'];
      const policy = AUTOSCALE_POLICIES.includes(as.policy) ? as.policy : 'ewma';

      // Concurrency-limit controller tuning.
      const limitMin = Number.isFinite(Number(as.limitMin))
        ? Math.max(1, Math.floor(Number(as.limitMin)))
        : 1;
      const limitMax = Number.isFinite(Number(as.limitMax))
        ? Math.max(limitMin, Math.floor(Number(as.limitMax)))
        : Math.max(this.maxSize, limitMin);
      const longWindowAlpha = Number.isFinite(Number(as.longWindowAlpha))
        ? Math.max(0.001, Math.min(1, Number(as.longWindowAlpha)))
        : DEFAULT_AUTOSCALE_LONG_WINDOW_ALPHA;
      const aimdBeta = Number.isFinite(Number(as.aimdBeta))
        ? Math.max(0.1, Math.min(0.99, Number(as.aimdBeta)))
        : DEFAULT_AUTOSCALE_AIMD_BETA;

      this._autoScale = {
        enabled: true,
        intervalMs,
        targetMs,
        alpha,
        cooldownMs,
        hysteresis,
        stepUp,
        stepDown,
        backoffFactor,
        backoffMaxMultiplier,
        backoffResetMs,
        policy,
        limitMin,
        limitMax,
        longWindowAlpha,
        aimdBeta,
      };
      // runtime backoff multiplier (starts at 1)
      this._autoScaleBackoffMultiplier = 1;
      /*
       * Adaptive concurrency state. `_adaptiveLimit` is the controller's
       * current belief about how many workers the pool should run, and is what
       * the 'aimd' / 'vegas' / 'gradient2' policies steer. The EWMA policy
       * ignores it and keeps the original latency-threshold behaviour.
       */
      this._adaptiveLimit = Math.max(limitMin, Math.min(limitMax, this.minSize || limitMin));
      this._longEwmaLatency = null;
      this._minLatencyWindow = Number.POSITIVE_INFINITY;
      this._lastAdaptiveLimit = this._adaptiveLimit;
      this._congestion = false;
      // start periodic autoscale tick
      try {
        this._autoScaleInterval = setSafeInterval(() => this._autoScaleTick(), intervalMs);
      } catch (e) {
        this._debugLog?.(e, 'autoScale: interval setup failed');
      }
    }
    // FEAT-007: opt-in metrics. Off by default, so the common case pays
    // nothing and allocates no closure.
    this._metrics = attach(this, 'pool', options);
  }

  /**
   * Log debug information about swallowed errors when debug logging is enabled.
   * @param {*} err - The swallowed error, or falsy when the call is informational.
   * @param {string} [msg]
   * @returns {void}
   * @private
   */
  _debugLog(err, msg) {
    try {
      if (typeof this._logger?.debug === 'function') {
        if (err) this._logger.debug(err, msg || 'swallowed error');
        else this._logger.debug(msg || 'swallowed error');
      }
    } catch (e) {
      try {
        if (typeof console !== 'undefined' && typeof console.debug === 'function')
          console.debug(e, msg || 'swallowed error');
      } catch (_) {
        // Last-resort sink failed too; there is nowhere left to report this.
      }
    }
  }

  /** Ensure the reaper interval exists; recreate it if missing. @private */
  _ensureReaper() {
    try {
      if (!this._reaperInterval) {
        this._reaperInterval = setSafeInterval(
          () => this._reapIdleWorkers(),
          Math.max(DEFAULT_REAPER_MIN_INTERVAL_MS, Math.floor(this.idleTimeout / 2))
        );
      }
    } catch (e) {
      this._debugLog?.(e, '_ensureReaper: setInterval failed');
    }
  }

  /*
   * Create and register a pending response entry for a given correlation id.
   * Returns `{ pendingPromise, correlationKey }` where `pendingPromise` is
   * the Promise that will be resolved/rejected when the response arrives
   * or when the per-call/pool timeout elapses.
   * @param {*} correlationId
   * @param {{wantResponse?: boolean, timeout?: number, correlationKey?: string}} [options]
   * @returns {{pendingPromise: Promise<any>, correlationKey: string|undefined}}
   * @private
   */
  _createPendingResponsePromise(correlationId, options) {
    const correlationKey = correlationId != null ? String(correlationId) : correlationId;
    let entry = null;
    const pendingPromise = new Promise((resolve, reject) => {
      // Reject (and clean up) any entry already registered under this key.
      // Overwriting it used to orphan the previous promise forever: its
      // `resolve`/`reject` closures became unreachable and its timer was
      // never cleared, so the caller hung with no diagnostic.
      const previous = this._pendingResponses.get(correlationKey);
      if (previous) {
        this._debugLog?.(
          null,
          'createPendingResponsePromise: duplicate correlationId, rejecting previous waiter'
        );
        this._cleanupPendingResponse(correlationKey, {
          rejectWith: (() => {
            const err = /** @type {Error & {code: 'ERR_POOL_DUPLICATE_CORRELATION_ID'}} */ (
              new Error(`duplicate correlationId: ${correlationKey}`)
            );
            err.code = 'ERR_POOL_DUPLICATE_CORRELATION_ID';
            return err;
          })(),
        });
      }
      entry = { resolve, reject, timer: null };
      const perCallTimeout = Number.isFinite(Number(options?.timeout))
        ? Math.max(0, Math.floor(Number(options?.timeout)))
        : Number.isFinite(Number(this._defaultAwaitResponseTimeout))
          ? this._defaultAwaitResponseTimeout
          : undefined;
      if (Number.isFinite(perCallTimeout) && perCallTimeout > 0) {
        entry.timer = setTimeout(() => {
          try {
            this._cleanupPendingResponse(correlationKey, {
              rejectWith: new Error('postMessage response timeout'),
            });
          } catch (e) {
            try {
              reject(new Error('postMessage response timeout'));
            } catch (e2) {
              this._debugLog?.(e2, 'createPendingResponsePromise: reject fallback failed');
            }
          }
        }, perCallTimeout);
      }
      this._pendingResponses.set(correlationKey, entry);
    });
    return { pendingPromise, correlationKey };
  }

  /**
   * Resolve a deferred message into the carrier this specific worker expects.
   *
   * This is where protocol negotiation is decided, and the reason it has to be
   * here rather than in `_prepareForTransfer` is that the target worker is not
   * known when a message is prepared: a queued item can be handed to any worker
   * by either drain site. Deciding at dispatch is what makes the decision
   * *per worker*, which is the whole point — a pool with one upgraded worker
   * and nine legacy ones is the state this feature exists for.
   *
   * Non-deferred items pass straight through, so `'framed'`, `'legacy'` and
   * every binary message keep their existing path untouched.
   *
   * @private
   * @param {import('./jsdoc-types.js').WorkerObj} obj - Target worker, if known.
   * @param {{message: *, transfer: (TransferList|undefined), deferred?: boolean}} prepared
   * @returns {{message: *, transfer: (TransferList|undefined)}}
   */
  _encodeForWorker(obj, prepared) {
    if (!prepared || prepared.deferred !== true) return prepared;
    if (this._messageCodec === 'negotiated' && obj?.protocol?.native) {
      const native = this._encodeNativeForWorker(prepared);
      if (native) return native;
    }
    // POOL-009: a queued item carrying a correlation id is uncacheable for the same
    // reason a direct one is - the id makes the encoded key unique per post.
    return this._frameObjectForTransfer(prepared.message, prepared.transfer, {
      cache: prepared.correlationId == null,
    });
  }

  /**
   * Wrap a deferred message in the native envelope, or return `null` when this
   * runtime cannot do it.
   *
   * The transfer list is the subtle part. A transfer list names buffers inside
   * the object being posted, and `postMessage` **detaches** them — so naming
   * the caller's buffers would detach the caller's data, which is a data-loss
   * bug that looks like a successful post. When the payload carries no binary
   * there is nothing to name, and the envelope is posted with no list and no
   * copy: the platform clones it, which is the whole reason for choosing this
   * carrier. When it does carry binary, a private copy is made first and *its*
   * buffers are transferred.
   *
   * @private
   * @param {PreparedItem} prepared - Already framed or marked `deferred`.
   * @returns {{message: object, transfer: (TransferList|undefined)}|null}
   */
  _encodeNativeForWorker(prepared) {
    if (!this._nativeCloneAvailable) return null;
    const source = prepared.message;
    let value = source;
    let transfer;
    if (collectTransferables(source).length > 0) {
      // Private copy: see above. `encodeNative` clones and returns the list for
      // the copy, which is exactly the pairing that is safe to transfer.
      const cloned = encodeNative(source);
      value = cloned.message;
      transfer = cloned.transfer;
    }
    try {
      return { message: encodeNativeEnvelope(value), transfer };
    } catch (err) {
      // A value the platform cannot clone (a function, a proxy, a getter that
      // throws). Falling back to the frame is right: the frame is the portable
      // path, and a worker that negotiated `native` still reads it.
      this._debugLog?.(err, '_encodeNativeForWorker: not cloneable, framing instead');
      return null;
    }
  }

  /**
   * Record what a worker says it can decode, and announce the change.
   *
   * The rules here are deliberately conservative, because a worker that
   * over-claims costs a broken message and a worker that under-claims costs
   * nothing but speed:
   *
   * - `native` is only granted when the runtime can structured-clone. A worker
   *   that advertises it on a runtime that cannot is talking about a carrier
   *   that does not exist here, and honouring that would throw per message.
   * - `json` is always retained. It is what the pool sends until this
   *   announcement lands, and a worker that claims `native` alone has not said
   *   it can read the messages it has already been sent.
   *
   * @private
   * @param {import('./jsdoc-types.js').WorkerObj} obj
   * @param {{codecs: string[]}} announcement
   */
  _applyCapabilities(obj, announcement) {
    const claimed = Array.isArray(announcement?.codecs) ? announcement.codecs : [];
    const codecs = ['json'];
    if (this._nativeCloneAvailable && claimed.includes('native')) codecs.push('native');
    const native = codecs.includes('native');
    const previous = obj?.protocol ? { ...obj.protocol } : null;
    if (previous && previous.native === native && previous.announced) return;
    if (obj) {
      obj.protocol = { codecs, native, announced: true };
    }
    try {
      this._bus.emit('pool:protocol', {
        workerId: obj?.id,
        codecs,
        previous: previous?.codecs ?? ['json'],
      });
    } catch (e) {
      this._debugLog?.(e, '_applyCapabilities: bus.emit failed');
    }
  }

  /**
   * Post a prepared message to a specific worker object and update bookkeeping.
   * Returns the `pendingPromise` when `wantResponse` is true, otherwise `true` on success.
   * On failure, rejects/cleans up the pending response when applicable and
   * returns `pendingPromise` (when awaiting) or `false`.
   * @param {import('./jsdoc-types.js').WorkerObj} obj
   * @param {{message: *, transfer: (TransferList|undefined)}} prepared
   * @param {number} startTime
   * @param {boolean} wantResponse
   * @param {string|undefined} correlationKey
   * @param {Promise<any>} pendingPromise
   * @returns {Promise<any>|boolean}
   * @private
   */
  _postToWorkerObj(obj, prepared, startTime, wantResponse, correlationKey, pendingPromise) {
    prepared = this._encodeForWorker(obj, prepared);
    // Bypass the wrapper for "plain object + explicit transfer list".
    //
    // `WorkerWrapper.postMessage` re-encodes a plain-object message to JSON and
    // substitutes the encoded buffer for it. That is the right default, and it
    // is wrong here: a caller who passes an object *together with* a transfer
    // list is saying "send this object as-is and transfer these buffers", and
    // the wrapper would silently substitute a `Uint8Array` for their object.
    // Posting to the underlying worker directly is what preserves that intent.
    //
    // `_underlying` is a private field of `WorkerWrapper`, so this reach-through
    // is an internal contract and is checked as one: `instanceof` for the
    // wrapper, and `typeof === 'function'` for the method. The previous
    // `obj?.worker?.['_underlying']?.postMessage` truthiness check also passed
    // for a non-function truthy value - a test spy, a half-constructed worker -
    // and then failed with a `TypeError: postMessage is not a function` that had
    // nothing to do with the caller's message.
    const underlying =
      obj?.worker instanceof WorkerWrapper ? /** @type {any} */ (obj.worker)._underlying : null;
    const canBypassWrapper =
      prepared != null &&
      prepared.message != null &&
      typeof prepared.message === 'object' &&
      !ArrayBuffer.isView(prepared.message) &&
      !(prepared.message instanceof ArrayBuffer) &&
      Array.isArray(prepared.transfer) &&
      prepared.transfer.length > 0 &&
      typeof underlying?.postMessage === 'function' &&
      isTransferListLive(prepared.transfer);

    if (canBypassWrapper) {
      try {
        underlying.postMessage(prepared.message, prepared.transfer);
        if (typeof obj._startTimes?.push === 'function') obj._startTimes.push(startTime);
        this._markPendingWorker(correlationKey, obj.id);
        obj.tasks++;
        this._activeTasks++;
        obj.lastActive = startTime;
        if (this._isIdle) this._updateIdleState();
        return wantResponse ? pendingPromise : true;
      } catch (err) {
        // Deliberately no retry on the wrapper path. A `postMessage` that
        // throws may already have detached part of the transfer list, so
        // re-posting the same buffers fails with `DataCloneError: ArrayBuffer
        // at index N has already been detached` - a message that reads like a
        // caller bug and hides the error that actually happened. The wrapper
        // path is not an equivalent retry either: it would re-encode the
        // message, which is the very substitution this bypass exists to avoid.
        return this._failPost(err, wantResponse, correlationKey, pendingPromise, {
          scope: 'postToWorkerObj: direct postMessage failed',
        });
      }
    }
    try {
      this._dispatchToWorker(obj, prepared, { correlationId: correlationKey, startTime });
      if (this._isIdle) this._updateIdleState();
      return wantResponse ? pendingPromise : true;
    } catch (err) {
      return this._failPost(err, wantResponse, correlationKey, pendingPromise, {
        scope: 'postToWorkerObj: wrapper postMessage failed',
      });
    }
  }

  /**
   * Report a failed `postMessage` and clean up the pending response for it.
   *
   * Single choke point for the failure half of `_postToWorkerObj`, so the two
   * posting paths (direct to the underlying worker, through the wrapper) cannot
   * drift on what the caller is told. The important property is that a
   * post that failed *after* possibly detaching buffers is still reported with
   * its **original** error - never with a downstream `DataCloneError` from a
   * retry against the same buffers.
   *
   * @param {any} err - The error thrown by `postMessage`.
   * @param {boolean} wantResponse - Whether the caller is awaiting a response.
   * @param {string|undefined} correlationKey - Pending-response key to reject.
   * @param {Promise<any>} pendingPromise - The caller's pending promise.
   * @param {{scope: string}} [info] - Debug-log scope.
   * @returns {Promise<any>|boolean} `pendingPromise` when awaiting a response,
   *   `false` otherwise - matching `postMessage`'s contract.
   * @private
   */
  /**
   * Post one prepared item to one worker, and account for it.
   *
   * The single dispatch choke point. There were eight `postMessage` call sites
   * before this, each with its own copy of the post-and-account sequence, and
   * they drifted in four different directions:
   *
   * - the single-worker batch fast path skipped the deferred encode, so every
   *   batched request reached the worker as raw JSON and failed at the first line
   *   (`POOL-001` — `unsupported protocol version 123`, since `{` is 123);
   * - the inline drain in `worker.onmessage` never recorded which worker took the
   *   task, so a queued `awaitResponse` promise could never be settled
   *   (`POOL-002`);
   * - `stopThePress` enqueued the caller's object with no preparation at all
   *   (`POOL-003`);
   * - only the direct path reported a failed post through `_failPost`, and only
   *   the batch loops and `broadcast` had their own idle-state policy.
   *
   * All three defects were *the same defect*. A property is checkable only when
   * there is one place that owns it, so a fourth copy of a sequence is a fourth
   * place to forget a step.
   *
   * @private
   * @param {*} workerObj - A `WorkerObj`. Left untyped to match the other
   *   private dispatch helpers here; annotating it stricter than what the worker
   *   records actually are would add an error at every call site for no gain.
   * @param {PreparedItem} prepared - Must be prepared. A `deferred` item is
   *   framed here, which is why every route can hand one over unchanged.
   * @param {{correlationId?: (string|undefined), startTime?: (number|undefined)}=} options
   *   `correlationId` for a task awaiting a response, so the pending entry can be
   *   tied to this worker; `startTime` when the caller already took a timestamp
   *   and wants every record in a batch or a broadcast to share it.
   * @returns {number} The `startTime` used, for a caller that has not taken one.
   */
  _dispatchToWorker(workerObj, prepared, options = {}) {
    const { correlationId, startTime = nowMs() } = options;
    // Resolve a deferred encode here rather than at each call site. A `deferred`
    // item is one whose framing is still owed, and posting it verbatim puts raw
    // bytes on the wire where the worker reads the first byte of a JSON body as
    // a protocol version — `unsupported protocol version 123 (expected 1)`, since
    // `{` is 123. That is the `POOL-001` failure, and it happened because the
    // single-worker batch fast path bypassed `postMessage` and so bypassed the
    // only place that knew about the marker.
    const item = prepared.deferred
      ? {
          ...this._frameObjectForTransfer(prepared.message, prepared.transfer, {
            cache: prepared.correlationId == null,
          }),
        }
      : prepared;

    const { worker } = workerObj;
    if (item.transfer?.length) worker.postMessage(item.message, item.transfer);
    else worker.postMessage(item.message);
    if (typeof workerObj._startTimes?.push === 'function') workerObj._startTimes.push(startTime);
    // **Every dispatch records which worker took the task.** Skipping this is
    // how a queued `awaitResponse` promise came to hang for good under
    // `awaitResponseTimeout: Infinity`: the task was dispatched and counted, but
    // `_rejectPendingForWorker` had no `workerId` to match, so termination could
    // never settle it. See `POOL-002`. `correlationId` is `undefined` for a
    // fire-and-forget message and `_markPendingWorker` returns immediately.
    this._markPendingWorker(correlationId, workerObj.id);
    workerObj.tasks += 1;
    this._activeTasks += 1;
    workerObj.lastActive = startTime;
    return startTime;
  }

  _recordQueueWait(wait) {
    if (!Number.isFinite(wait)) return;
    const count = this._queueWaitWelfordCount + 1;
    const delta = wait - this._queueWaitWelfordMean;
    this._queueWaitWelfordMean += delta / count;
    this._queueWaitWelfordM2 += delta * (wait - this._queueWaitWelfordMean);
    this._queueWaitWelfordCount = count;
    this._queueWaitMin = Math.min(this._queueWaitMin, wait);
    this._queueWaitMax = Math.max(this._queueWaitMax, wait);
  }

  /**
   * Report a batched post that could not be dispatched.
   *
   * `postMessageBatch` answers with a per-item boolean, so a failure is a
   * `false` in an array and — before this — nothing else. Two of the three
   * failure sites caught the error and dropped it on the floor: no log, no
   * `pool:error` event, no count. A caller seeing `false` could not tell a
   * dispatch failure from a busy worker, and an operator had no way to know a
   * batch had silently lost half its items. The third site already logged and
   * emitted, which is the pattern; this gives all three one, and adds the count.
   *
   * Every step is individually guarded because this runs **inside a `catch`**:
   * a logger or an event bus that throws would replace the original failure with
   * its own, and the item would be reported as neither failed nor sent.
   *
   * @param {any} err - The error thrown while dispatching.
   * @param {string} scope - Which site failed, for the log and the event.
   * @returns {false} So a call site can assign it straight to its result slot.
   * @private
   */
  _reportPostFailure(err, scope) {
    this._postFailures += 1;
    try {
      this._logger.error(err, `${scope}: failed to post`);
    } catch (e) {
      this._debugLog?.(e, `${scope}: logger.error failed`);
    }
    try {
      this._bus.emit('pool:error', { phase: 'postMessageBatch', error: err, scope });
    } catch (e) {
      this._debugLog?.(e, `${scope}: bus.emit failed`);
    }
    return false;
  }

  /**
   * Report a failed `postMessage` and clean up the pending response for it.
   * @param {any} err - The error thrown by `postMessage`.
   * @param {boolean} wantResponse - Whether the caller is awaiting a response.
   * @param {string|undefined} correlationKey - Pending-response key to reject.
   * @param {Promise<any>} pendingPromise - The caller's pending promise.
   * @param {{scope: string}} [info] - Debug-log scope.
   * @returns {Promise<any>|boolean} `pendingPromise` when awaiting a response,
   *   `false` otherwise - matching `postMessage`'s contract.
   * @private
   */
  _failPost(err, wantResponse, correlationKey, pendingPromise, info) {
    if (wantResponse && correlationKey) {
      try {
        this._cleanupPendingResponse(correlationKey, { rejectWith: err });
      } catch (e) {
        this._debugLog?.(e, `${info?.scope ?? 'failPost'}: cleanupPendingResponse failed`);
      }
      try {
        this._logger.error(err, 'Failed to postMessage to worker');
      } catch (e) {
        this._debugLog?.(e, `${info?.scope ?? 'failPost'}: logger.error failed`);
      }
      return pendingPromise;
    }
    try {
      this._logger.error(err, 'Failed to postMessage to worker');
    } catch (e) {
      this._debugLog?.(e, `${info?.scope ?? 'failPost'}: logger.error failed`);
    }
    return false;
  }

  /**
   * Attempt to grow the pool by adding a worker and dispatching the message.
   * Preserves the same pending-response cleanup semantics as inline logic.
   * @param {*} message
   * @param {TransferList} [transfer]
   * @param {Object} [options]
   * @param {number} startTime
   * @param {boolean} [wantResponse]
   * @param {string} [correlationId]
   * @param {number} [timeout]
   * @returns {Promise<any>|boolean}
   * @private
   */
  _tryGrowPool(
    message,
    transfer,
    options,
    startTime,
    wantResponse,
    correlationKey,
    pendingPromise
  ) {
    let obj;
    try {
      obj = this._addWorkerInstance();
    } catch (err) {
      try {
        this._logger.error(err, 'Failed to grow pool');
      } catch (e) {
        this._debugLog?.(e, 'tryGrowPool: logger.error failed');
      }
      try {
        this._bus.emit('pool:error', { phase: 'grow', error: err });
      } catch (e) {
        this._debugLog?.(e, 'tryGrowPool: bus.emit failed');
      }
      if (wantResponse && correlationKey) {
        try {
          this._cleanupPendingResponse(correlationKey, { rejectWith: err });
        } catch (e) {
          this._debugLog?.(e, 'tryGrowPool: cleanupPendingResponse failed');
        }
        return pendingPromise;
      }
      return false;
    }
    if (!obj) {
      if (wantResponse && correlationKey) {
        try {
          this._cleanupPendingResponse(correlationKey, {
            rejectWith: new Error('failed to add worker'),
          });
        } catch (e) {
          this._debugLog?.(e, 'tryGrowPool: cleanupPendingResponse failed');
        }
        return pendingPromise;
      }
      return false;
    }
    const prepared = this._prepareForTransfer(message, transfer, options);
    return this._postToWorkerObj(
      obj,
      prepared,
      startTime,
      wantResponse,
      correlationKey,
      pendingPromise
    );
  }

  /**
   * Resolve and validate the per-item correlation ids for a batch that expects
   * responses.
   *
   * Two failure modes are checked, and both are checked *before* any dispatch:
   *
   * 1. A duplicate **within** the batch. A `correlationIdFactory` is caller
   *    code; a constant or a sloppy one returns the same id twice, and the
   *    second `postMessage` under a live key rejects the first waiter and
   *    takes the key over. The caller would hold a batch where one promise is
   *    already rejected and the last result resolves for all of them.
   * 2. A collision with an id that is **already in flight** from an earlier
   *    call. Same mechanism, same outcome, and it is silently the caller's
   *    fault because the factory is a global naming scheme, not a local one.
   *
   * @param {{message:*,transfer?:Transferable[]}[]} items - The batch items.
   * @param {Function} factory - The caller's `correlationIdFactory`.
   * @returns {string[]} One validated id per item, positionally aligned.
   * @throws {Error} `ERR_POOL_DUPLICATE_CORRELATION_ID` on the first collision.
   * @private
   */
  _resolveBatchCorrelationIds(items, factory) {
    const ids = new Array(items.length);
    const seen = new Set();
    for (let i = 0; i < items.length; i++) {
      const id = String(factory(i, items[i] || {}));
      if (seen.has(id) || this._pendingResponses.has(id)) {
        const err = /** @type {Error & {code: 'ERR_POOL_DUPLICATE_CORRELATION_ID'}} */ (
          new Error(
            `postMessageBatch correlationIdFactory produced a duplicate correlationId: "${id}" (item ${i})`
          )
        );
        err.code = 'ERR_POOL_DUPLICATE_CORRELATION_ID';
        throw err;
      }
      seen.add(id);
      ids[i] = id;
    }
    return ids;
  }

  /**
   * Reserve room for `count` more tasks in the task queue, honouring
   * `maxQueueLength` and the configured `queuePolicy`.
   *
   * Without a cap this is a no-op and returns `count`, which is what keeps the
   * pre-2.0 behaviour intact: `queuePolicy: 'enqueue'` grew the queue until the
   * process ran out of memory, with no event and no error. The cap exists to
   * make that overflow *observable*, so the interesting decision is **which
   * task gets refused**:
   *
   * - `drop-oldest` keeps its documented meaning: evict the oldest to make room
   *   for the newest, so the queue length never exceeds the cap.
   * - every other policy refuses the **incoming** task. That is the honest
   *   reading of a caller-provided bound - the newest arrival is the one that
   *   did not fit, and refusing it keeps the work already accepted.
   *
   * @param {number} count - How many tasks are about to be queued.
   * @returns {number} How many of them may be queued. The remainder must be
   *   refused by the caller.
   * @private
   */
  _reserveQueueSlots(count) {
    const cap = this._maxQueueLength;
    if (!Number.isFinite(cap)) return count;
    let room = cap - this.queue.length;
    if (room >= count) return count;
    if (this._queuePolicy === 'drop-oldest') {
      let evict = count - room;
      while (evict > 0 && this.queue.length > 0) {
        evict--;
        const dropped = this.queue.shift();
        if (dropped?.correlationId != null) {
          this._cleanupPendingResponse(dropped.correlationId, {
            rejectWith: new Error('postMessage queued task dropped by policy'),
          });
        }
      }
      room = cap - this.queue.length;
    }
    return room > 0 ? room : 0;
  }

  /**
   * Enqueue or reject a prepared message according to the configured queue policy.
   * Returns `pendingPromise`/`true`/`false` to match `postMessage` semantics.
   *
   * @param {PreparedItem} prepared - Already prepared by `_prepareForTransfer`
   *   or `prepareBuffers`. Taking the item whole is deliberate: a signature of
   *   `(message, transfer)` would let a caller hand in an unprepared object,
   *   which is the shape of the POOL-003 defect.
   * @private
   */
  _enqueueOrReject(prepared, wantResponse, correlationKey, pendingPromise, options) {
    const policy = this._queuePolicy;
    if (policy === 'reject') {
      if (wantResponse && correlationKey) {
        this._cleanupPendingResponse(correlationKey, {
          rejectWith: new Error('postMessage rejected by queue policy'),
        });
        return pendingPromise;
      }
      return false;
    }
    if (policy === 'drop-newest' && this.queue.length > 0) {
      if (wantResponse && correlationKey) {
        this._cleanupPendingResponse(correlationKey, {
          rejectWith: new Error('postMessage rejected by queue policy'),
        });
        return pendingPromise;
      }
      return false;
    }
    if (policy === 'drop-oldest' && this.queue.length > 0) {
      const dropped = this.queue.shift();
      if (dropped?.correlationId != null) {
        this._cleanupPendingResponse(dropped.correlationId, {
          rejectWith: new Error('postMessage queued task dropped by policy'),
        });
      }
    } else if (this._reserveQueueSlots(1) === 0) {
      // The queue is at `maxQueueLength`. `drop-oldest` above already made
      // room, so reaching here means the incoming task is the one that does
      // not fit.
      if (wantResponse && correlationKey) {
        this._cleanupPendingResponse(correlationKey, {
          rejectWith: (() => {
            const err = /** @type {Error & {code: 'ERR_POOL_QUEUE_FULL'}} */ (
              new Error(
                `postMessage rejected: task queue is full (maxQueueLength ${this._maxQueueLength})`
              )
            );
            err.code = 'ERR_POOL_QUEUE_FULL';
            return err;
          })(),
        });
        return pendingPromise;
      }
      return false;
    }
    /** @type {PreparedItem & {correlationId?: string, priority?: number}} */
    const queuedItem = {
      message: prepared.message,
      transfer: prepared.transfer,
      enqueuedAt: nowMs(),
    };
    if (options?.deadlineAt !== undefined) queuedItem.deadlineAt = options.deadlineAt;
    if (prepared.deferred === true) queuedItem.deferred = true;
    if (wantResponse && correlationKey) queuedItem.correlationId = correlationKey;
    if (options?.priority != null) queuedItem.priority = options.priority;
    this.queue.push(queuedItem);
    try {
      if (
        Number.isFinite(this._queueHighThreshold) &&
        this.queue.length > this._queueHighThreshold &&
        !this._queueHighCrossed
      ) {
        this._queueHighCrossed = true;
        this._bus.emit('pool:queue:high', {
          length: this.queue.length,
          threshold: this._queueHighThreshold,
        });
      }
    } catch (e) {
      this._debugLog?.(e, 'enqueueOrReject: bus.emit failed');
    }
    this._updateIdleState();
    return wantResponse ? pendingPromise : true;
  }

  /**
   * Single choke point for retiring a worker from the pool.
   *
   * Every removal path - `shutdown()`, `removeWorker()`, `resize()`,
   * `_autoScaleTick()`, `_reapIdleWorkers()` and `_resetPoolForStopThePress()`
   * - routes through here so the active-task accounting, the terminated-worker
   * statistics and the underlying-worker mapping can no longer drift apart
   * between paths (the idle reaper previously skipped the statistics
   * entirely, inflating `getStats().performance.timePerTask` over time).
   *
   * Note: this deliberately does **not** remove the entry from `this.workers`;
   * callers own the array bookkeeping (some paths pop, some swap-remove, the
   * shutdown path clears the whole list).
   *
   * @param {WorkerObj|null} workerObj - Worker entry to retire.
   * @param {string} [reason] - Why the worker is being removed, used for
   *   debug logging only.
   * @returns {number|null} The retired worker id, or `null` when nothing was
   *   retired.
   * @private
   */
  _terminateWorker(workerObj, reason = 'unknown') {
    if (!workerObj) return null;
    const id = workerObj.id ?? null;
    // Tasks the pool believed were in flight on this worker are no longer
    // tracked: `resize()`/`removeWorker()` terminate busy workers too, and the
    // response that would normally settle them will never arrive.
    //
    // That last part used to be a comment and nothing else. The count was
    // decremented, the worker was terminated, and the caller's `awaitResponse`
    // promise was left to time out on its own — 30 seconds by default, and
    // forever under `awaitResponseTimeout: Infinity`. Every other path that
    // abandons a pending response (queue eviction, post failure, pool-growth
    // failure, shutdown) rejects it, so this was the one way to lose a
    // response silently. Rejecting here is what makes "the worker is gone"
    // observable at the moment it happens.
    if (workerObj.tasks > 0) this._decrementActiveTasks(workerObj.tasks);
    workerObj.tasks = 0;
    this._rejectPendingForWorker(id, reason);
    // Mark the worker settled *after* the drain, and before `terminate()`. A
    // `message` already in flight from this worker will still reach the pool
    // handler - `terminate()` stops new work, it does not recall a dispatched
    // event - and without this it would decrement the global counter a second
    // time for a task that has already been accounted for here.
    //
    // The old `Math.max(0, ...)` clamp on `workerObj.tasks` could not prevent
    // this: it kept the *per-worker* count from going negative, while the
    // *global* `_activeTasks` was the thing being double-decremented. The count
    // then fell below the number of tasks actually running, so `getStats()
    // .activeTasks` under-reported, `_isIdle` could go true with work
    // outstanding, and `drain()` resolved early against a pool that was not
    // idle.
    workerObj.tasksSettled = true;
    try {
      // Disposed, not just terminated. `terminate()` stops the worker; it does not
      // detach the three native listeners `WorkerAgnostic` wired onto it at
      // construction, and each one closes over `this` pool. Disposing first means
      // a message that was already in flight reaches nobody — which is also what
      // the `tasksSettled` guard above was written for, so the two agree rather
      // than one papering over the other.
      workerObj._agnostic?.dispose();
    } catch (err) {
      this._debugLog?.(err, `_terminateWorker(${reason}): worker dispose failed`);
    }
    try {
      workerObj.worker?.terminate();
    } catch (err) {
      this._debugLog?.(err, `_terminateWorker(${reason}): worker.terminate failed`);
    }
    this._deleteWorkerUnderlyingMapping(workerObj);
    this._terminatedWorkerTaskCountsTotal += workerObj.completedTasks || 0;
    this._terminatedWorkerTaskCountsCount += 1;
    return id;
  }

  /**
   * Reject every pending response that was dispatched to a worker that is being
   * retired. The response for those tasks lives in that worker and is never
   * coming, so the promise is settled here rather than on its timeout.
   *
   * Scans the pending map rather than keeping a per-worker index, because the
   * number of outstanding responses is small and bounded by
   * `awaitResponseTimeout`, while the index would have to be maintained on the
   * response path too — and a per-worker index that is updated in one place and
   * not another silently under-rejects, which is the failure this exists to
   * prevent.
   *
   * @param {number|string|null} workerId - The worker being retired.
   * @param {string} [reason] - Why, used in the error message only.
   * @returns {number} How many pending responses were rejected.
   * @private
   */
  _rejectPendingForWorker(workerId, reason = 'unknown') {
    if (workerId == null || !this._pendingResponses?.size) return 0;
    const doomed = [];
    try {
      for (const [key, entry] of this._pendingResponses) {
        if (entry?.workerId === workerId) doomed.push(key);
      }
    } catch (err) {
      this._debugLog?.(err, '_rejectPendingForWorker: scan failed');
      return 0;
    }
    for (const key of doomed) {
      try {
        this._cleanupPendingResponse(key, {
          rejectWith: poolRefusal(
            'ERR_POOL_WORKER_TERMINATED',
            `postMessage failed: worker ${workerId} was terminated (${reason}) before responding`
          ),
        });
      } catch (err) {
        this._debugLog?.(err, '_rejectPendingForWorker: cleanup failed');
      }
    }
    return doomed.length;
  }

  /**
   * Record which worker a pending response was dispatched to, so retirement
   * can find it. Stamped after the post succeeds: a response that never left
   * the pool is not owed anything by the worker it was aimed at.
   *
   * @param {string|number|null|undefined} correlationKey - The pending key.
   * @param {number|string|null} workerId - The worker that received the task.
   * @returns {void}
   * @private
   */
  _markPendingWorker(correlationKey, workerId) {
    if (correlationKey == null || workerId == null) return;
    try {
      const entry = this._pendingResponses.get(String(correlationKey));
      if (entry) entry.workerId = workerId;
    } catch (err) {
      this._debugLog?.(err, '_markPendingWorker: failed');
    }
  }

  /**
   * Throws when the pool has been shut down. Called from every public entry
   * point that would otherwise dispatch, enqueue or grow workers.
   * @private
   */
  _assertNotTerminated() {
    if (!this._terminated) return;
    const err = /** @type {Error & {code: 'ERR_POOL_TERMINATED'}} */ (
      new Error('PowerPool has been shut down')
    );
    err.code = 'ERR_POOL_TERMINATED';
    throw err;
  }

  /**
   * Clear lifecycle timer intervals used by the pool.
   * @private
   */
  _clearLifecycleIntervals() {
    try {
      if (this._reaperInterval) {
        clearInterval(this._reaperInterval);
        this._reaperInterval = null;
      }
    } catch (e) {
      this._debugLog?.(e, 'clearLifecycleIntervals: clearInterval(reaper) failed');
    }
    try {
      if (this._autoScaleInterval) {
        clearInterval(this._autoScaleInterval);
        this._autoScaleInterval = null;
      }
    } catch (e) {
      this._debugLog?.(e, 'clearLifecycleIntervals: clearInterval(autoScale) failed');
    }
  }

  /**
   * Shutdown the pool: clear timers, reject pending responses, terminate workers,
   * and clear internal queues. This is a full stop that prevents background
   * timers from keeping the process alive.
   *
   * Shutdown is **final**: the pool refuses every subsequent `postMessage()`,
   * `postMessageBatch()`, `addWorker()` and `resize()` with an
   * `ERR_POOL_TERMINATED` error rather than silently recreating workers.
   * Create a new `PowerPool` to start again.
   *
   * @returns {void}
   */
  shutdown() {
    if (this._terminated) return;
    this._terminated = true;
    this._clearLifecycleIntervals();

    // reject pending responses (centralized to avoid races)
    try {
      for (const [cid] of this._pendingResponses) {
        try {
          this._cleanupPendingResponse(cid, {
            rejectWith: new PowerPoolShutdownError('pool:shutdown'),
          });
        } catch (e) {
          this._debugLog?.(e, 'shutdown: cleanup pending response');
        }
      }
      // Ensure the map is empty in case individual cleanup failed
      try {
        if (typeof this._pendingResponses?.clear === 'function') this._pendingResponses.clear();
      } catch (e) {
        this._debugLog?.(e, 'shutdown: pendingResponses.clear failed');
      }
    } catch (e) {
      this._debugLog?.(e, 'shutdown: iterate pending responses');
    }

    // terminate workers
    const _terminated = [];
    try {
      for (const w of this.workers) {
        const id = this._terminateWorker(w, 'shutdown');
        if (id != null) _terminated.push(id);
      }
    } catch (e) {
      this._debugLog?.(e, 'shutdown: terminate workers loop');
    }

    // clear underlying -> worker map to avoid retaining references
    try {
      if (this._underlyingToWorkerObj) this._underlyingToWorkerObj.clear();
    } catch (e) {
      this._debugLog?.(e, 'shutdown: underlyingToWorkerObj.clear failed');
    }

    // emit pool:scale for shutdown removals
    if (_terminated.length) {
      this._bus.emit('pool:scale', {
        action: 'remove',
        reason: 'shutdown',
        terminated: _terminated,
        count: _terminated.length,
      });
    }

    // reset state
    this.workers = [];
    this.queue = new PowerQueue();
    this._queueHighCrossed = false;
    this._activeTasks = 0;

    // Emit idle so any in-flight `drain()` promises resolve instead of
    // hanging forever (the pool is now idle/terminated and will never
    // dispatch the synthetic `pool:idle` event through the normal path).
    this._updateIdleState();
  }

  /**
   * Encode a plain object to a Uint8Array, using a small cache to avoid
   * repeated encoding work for identical messages. Returns a Uint8Array.
   * @private
   * @param {Object} obj
   * @returns {Uint8Array}
   */
  /**
   * Wrap an encoded JSON body in a `PowerMessageCodec` envelope.
   *
   * The frame is built over a single `Uint8Array` so the existing transfer and
   * slicing logic above is unchanged; the header is six bytes, so this is a
   * `set` rather than a second allocation plus a copy.
   *
   * @private
   * @param {Uint8Array} body - Encoded JSON payload.
   * @returns {Uint8Array} The framed message.
   */
  _encodeForTransfer(obj, { cache: useCache = true } = {}) {
    try {
      // POOL-009. **A message awaiting a response never hits this cache, so consulting
      // it is pure cost and inserting is worse than cost.** Measured with two identical
      // `postMessage` calls: two fire-and-forget posts leave `_encodeCache.size` at 1 -
      // the second hits. Two posts with `awaitResponse` take it to 2: a unique key per
      // post, so every one is a guaranteed miss that also *inserts*, evicting an entry
      // that could have been reused and growing `_encodeCacheBytes`.
      //
      // Bypassed rather than fixed at the key. The structural fix - a correlation id in
      // the frame header rather than the body - is a 3.0 change: it breaks every worker
      // that echoes `data.correlationId`. Until then the honest answer is not to pretend
      // the entry is cacheable.
      if (!useCache) return o2u8(obj);
      const s = JSON.stringify(obj);
      // Avoid caching extremely large JSON keys which could bloat the
      // encode cache. For very large serialized payloads, skip caching
      // and return the encoded Uint8Array directly.
      if (typeof s === 'string' && s.length > ENCODE_CACHE_LARGE_KEY_LENGTH) {
        return o2u8(obj);
      }
      const hit = this._encodeCache.get(s);
      if (hit) {
        // Move to the end to mark as recently used (LRU behavior).
        try {
          this._encodeCache.delete(s);
          this._encodeCache.set(s, hit);
        } catch (e) {
          /* ignore cache update errors */
        }
        return hit;
      }
      // Reuse the already-computed JSON string `s` as the cache key AND as the
      // source for encoding, so we don't `JSON.stringify` the message twice on
      // a cache miss (o2u8 would otherwise re-stringify internally).
      const u8 = o2u8(obj, s);
      // Evict least-recently-used (oldest insertion) when over entry-count
      // limit or when adding this entry would exceed the byte-size limit.
      const willBeBytes = u8?.byteLength || 0;
      const needEviction = () =>
        this._encodeCache.size >= this._encodeCacheLimit ||
        (this._encodeCacheByteLimit !== Infinity &&
          this._encodeCacheBytes + willBeBytes > this._encodeCacheByteLimit);
      // Batch-evict oldest entries to reduce Map iterator/delete churn
      while (needEviction()) {
        const keysToDelete = [];
        const it = this._encodeCache.keys();
        const BATCH = 10;
        while (needEviction() && keysToDelete.length < BATCH) {
          const nxt = it.next();
          if (nxt.done) break;
          keysToDelete.push(nxt.value);
        }
        if (!keysToDelete.length) break;
        for (const k of keysToDelete) {
          try {
            const removed = this._encodeCache.get(k);
            const removedBytes = typeof removed?.byteLength === 'number' ? removed.byteLength : 0;
            this._encodeCacheBytes = Math.max(0, this._encodeCacheBytes - removedBytes);
          } catch (e) {
            /* ignore bookkeeping errors */
          }
          this._encodeCache.delete(k);
        }
      }
      this._encodeCache.set(s, u8);
      if (u8?.byteLength) this._encodeCacheBytes += u8.byteLength;
      // GAP-011 / POOL-009. **The buffer about to be handed to a caller must not be
      // transferred, and until now that was a doc note plus a detached-buffer pre-check.**
      // The pre-check catches the *second* transfer and not the first, which is the one
      // that matters: after the first, this entry is a zero-length husk that the next hit
      // returns, and the payload arrives at the worker empty with nothing thrown anywhere.
      //
      // `markAsUntransferable` moves the failure to the call site that made the mistake,
      // because the platform enforces it: a marked buffer listed for transfer is refused
      // rather than detached. **That is a behaviour change and it is the
      // point of the row** - silent corruption becomes a loud error - so it is recorded in
      // the changeset rather than absorbed here.
      markUntransferable(u8?.buffer);
      return u8;
    } catch (err) {
      // Fall back to direct encoding attempt
      return o2u8(obj);
    }
  }

  /**
   * Prepare an array of transferable buffers for a batch of items.
   * Each item may be a plain object, a TypedArray/ArrayBuffer view, or
   * an object `{ message, transfer? }`. The returned array contains
   * normalized `{ message, transfer }` entries ready for `postMessageBatch`.
   * ## `clone` defaults to `false`, and the slice it avoided was the expensive part
   *
   * `clone: true` copied every encoded buffer (`u8.slice()`) so it could be
   * **transferred** rather than copied by the structured clone. That looked like
   * the fast path: a transfer is zero-copy, so the copy must be worth avoiding.
   *
   * It is not, and it is not close. Over a Zipf-ish repeat mix of 200
   * 200-byte messages, comparing one variable at a time:
   *
   * | path | per message |
   * |---|---:|
   * | encode + cache, `slice()`, transfer (the old default) | 2942 ns |
   * | encode + cache, hand the cached buffer over to be copied | **1557 ns** |
   * | encode every time, `slice()`, transfer (no cache) | 3441 ns |
   *
   * The explicit `slice()` costs ~1385 ns — a JS-level `memcpy` of the whole
   * payload — and the structured-clone copy it was avoiding is a *native* one.
   * Paying an interpreted copy to dodge a native copy loses, and by enough that
   * it roughly halves the cost of the message path.
   *
   * The encode cache is emphatically **not** the problem: dropping it costs
   * ~1900 ns, nearly twice what the slice costs. It stays.
   *
   * With `clone: false` the cached buffer is handed to `postMessage` and the
   * runtime copies it, so the cache entry is never detached. The old warning to
   * "do NOT transfer those buffers if `clone:false`" is now the only rule, and
   * it is honoured automatically: the transfer list is `undefined` in this mode.
   *
   * Pass `{ clone: true }` to get a private transferable copy back — the
   * right choice when the caller wants to keep the payload alive on this side
   * and hand a detachable buffer to the worker.
   *
   * @param {Array<any|{message:any,transfer?:Transferable[]}>} items
   * @param {{clone?:boolean}=} options - `clone` defaults to `false`; see above.
   * @returns {PreparedItem[]}
   */
  prepareBuffers(items, options = {}) {
    if (!Array.isArray(items)) throw new Error('prepareBuffers expects an array');
    const { clone = false, zeroCopy = false } = options;
    /** @type {PreparedItem[]} */
    const out = new Array(items.length);
    for (let i = 0; i < items.length; i++) {
      const it =
        items[i] && typeof items[i] === 'object' && 'message' in items[i]
          ? items[i]
          : { message: items[i] };
      const msg = it.message;
      const tr = it.transfer;
      if (tr) {
        out[i] = { message: msg, transfer: tr };
        continue;
      }
      // plain object -> encode via cache
      const isPlainObject =
        msg !== null &&
        typeof msg === 'object' &&
        !ArrayBuffer.isView(msg) &&
        !(msg instanceof ArrayBuffer);
      if (isPlainObject) {
        if (zeroCopy) {
          out[i] = { message: msg, transfer: undefined };
          continue;
        }
        // **A pre-encoded body is not a framed message.** `clone: false` hands
        // back the shared encode-cache body, and framing wraps that body in a
        // new header — a new buffer, per call. So under any codec that frames,
        // the cached body cannot be both shared and correct on the wire, and
        // posting it verbatim is what made every batched request fail at the
        // first line: the worker read `{` (123) as a protocol version and
        // reported `unsupported protocol version 123 (expected 1)`.
        //
        // Two honest answers, and which one is right depends on the mode:
        //
        // - `clone: true` asks for a *private transferable* buffer, and a frame
        //   is already private, so frame it now and the work is done up front.
        //   This is the mode that can actually save the caller an encode.
        // - `clone: false` is only meaningful under `'legacy'`, where the
        //   cached body *is* the wire format. Otherwise mark the item `deferred`
        //   and let dispatch frame it — the same mechanism `'negotiated'` uses,
        //   and the only one that keeps the cache shareable.
        if (clone || this._messageCodec === 'legacy') {
          try {
            const u8 = this._encodeForTransfer(msg);
            const buf = clone ? u8.slice() : u8;
            out[i] = {
              message: buf,
              transfer: clone ? [buf.buffer] : undefined,
              deferred: this._messageCodec !== 'legacy',
            };
            // Under a framing codec `clone: true` must still produce a *frame*,
            // not a bare body, so redo it through the shared framer.
            if (this._messageCodec !== 'legacy') {
              out[i] = { ...this._frameObjectForTransfer(msg, tr), deferred: false };
            }
            continue;
          } catch (err) {
            out[i] = { message: msg, transfer: undefined };
            continue;
          }
        }
        out[i] = { message: msg, transfer: tr, deferred: true };
        continue;
      }
      // ArrayBuffer or ArrayBuffer view -> make transferable in one normalized fast path.
      if (msg instanceof ArrayBuffer || ArrayBuffer.isView(msg)) {
        const transferTarget = msg instanceof ArrayBuffer ? msg : msg.buffer;
        out[i] = { message: msg, transfer: [transferTarget] };
        continue;
      }
      // fallback: keep as-is
      out[i] = { message: msg, transfer: undefined };
    }
    return out;
  }

  /**
   * Class-level helper to prepare a message and optional transfer list for posting to a worker.
   * Accepts `opts` with `zeroCopy` flag to control forwarding of raw buffers.
   *
   * The single preparation path. `prepareBuffers` used to be a third copy of this
   * logic and drifted from it — see {@link PreparedItem} for what that cost.
   *
   * @private
   * @returns {PreparedItem}
   */
  _prepareForTransfer(msg, tr, opts) {
    const zeroCopy = Boolean(opts?.zeroCopy);
    if (msg instanceof Uint8Array || ArrayBuffer.isView(msg) || msg instanceof ArrayBuffer) {
      const transferTarget = msg instanceof ArrayBuffer ? msg : msg.buffer;
      if (!tr) {
        // Binary is framed under the `raw` codec too, so a worker always sees
        // the same protocol regardless of what it was handed. Without this, an
        // object message arrived framed and a binary message arrived bare, and
        // the worker had no way to tell - reintroducing exactly the sniffing
        // the codec exists to remove. An explicit `transfer` list still means
        // "I am sending this exact buffer, already in the form I want", so that
        // path is left alone.
        if (this._messageCodec === 'framed' && isRawPayload(msg)) {
          try {
            const framed = encodeMessage(msg, { codec: 'raw' });
            return { message: framed, transfer: [framed.buffer] };
          } catch (err) {
            this._debugLog?.(err, '_prepareForTransfer: framing binary failed');
          }
        }
        if (transferTarget?.byteLength === 0) {
          try {
            const copy = msg instanceof ArrayBuffer ? msg.slice(0) : new Uint8Array(msg);
            return { message: copy, transfer: [copy.buffer] };
          } catch (err) {
            return { message: msg, transfer: undefined };
          }
        }
        return { message: msg, transfer: [transferTarget] };
      }
      if (Array.isArray(tr)) {
        return { message: msg, transfer: tr };
      }
      if (tr.length === 0) {
        return { message: msg, transfer: [transferTarget] };
      }
      const arr = [];
      let found = false;
      for (const item of tr) {
        arr.push(item);
        if (item === transferTarget) found = true;
      }
      if (!found) arr.push(transferTarget);
      return { message: msg, transfer: arr };
    }

    const isPlainObject =
      msg !== null &&
      typeof msg === 'object' &&
      !ArrayBuffer.isView(msg) &&
      !(msg instanceof ArrayBuffer);
    if (isPlainObject) {
      if (zeroCopy) return { message: msg, transfer: tr };
      // Under `'negotiated'` the carrier is a per-worker decision, and the
      // target worker is not known yet on the enqueue path — a queued item can
      // land on any worker. Deferring the encode to dispatch is what makes
      // per-worker negotiation possible at all, and it is also what stops a
      // native worker being charged for a JSON encode it never uses.
      if (this._messageCodec === 'negotiated') {
        return { message: msg, transfer: tr, deferred: true };
      }
      // POOL-009. `opts` is the caller's own options, and `awaitResponse` there is what
      // makes the encoded key unique per post. Matched on the same two fields the
      // pending-response path uses (`powerPool.js:2866`), so the two cannot disagree
      // about what "wants a response" means.
      const wantsResponse = Boolean(opts?.awaitResponse || opts?.correlationId != null);
      return this._frameObjectForTransfer(msg, tr, { cache: !wantsResponse });
    }
    return { message: msg, transfer: tr };
  }

  /**
   * Encode a plain-object message as a framed JSON body.
   *
   * Split out of `_prepareForTransfer` so the deferred (`'negotiated'`) path and
   * the direct path share one implementation: two copies of the transfer-list
   * munging would drift, and the transfer list is where a leak lives.
   *
   * @private
   * @param {object} msg
   * @param {TransferList|undefined} tr
   * @returns {PreparedItem}
   */
  _frameObjectForTransfer(msg, tr, opts) {
    try {
      // `_encodeForTransfer` returns the cached JSON body; framing is a cheap
      // header wrap, so the encode cache is still what absorbs the
      // stringify/encode cost.
      //
      // `opts.cache` is POOL-009's bypass, threaded from the caller that knows whether
      // this message carries a per-post correlation id.
      const body = this._encodeForTransfer(msg, { cache: opts?.cache });
      // `'negotiated'` reaches here only for a worker that did not advertise,
      // and for that worker the answer is the frame — the same bytes a
      // `'framed'` pool posts. Branching on `!== 'legacy'` rather than
      // `=== 'framed'` is what keeps the fallback carrier identical between
      // the two modes; a third mode added later inherits it.
      const u8 = this._messageCodec === 'legacy' ? body : frameEncodedJson(body);
      const buf = u8.slice();
      let transferList = tr;
      if (!transferList || (Array.isArray(transferList) && transferList.length === 0)) {
        transferList = [buf.buffer];
      } else if (!Array.isArray(transferList)) {
        if (transferList.length === 0) {
          transferList = [buf.buffer];
        } else {
          const arr = [];
          let found = false;
          for (const item of transferList) {
            arr.push(item);
            if (item === buf.buffer) found = true;
          }
          if (!found) arr.push(buf.buffer);
          transferList = arr;
        }
      } else {
        let found = false;
        for (const item of transferList) {
          if (item === buf.buffer) {
            found = true;
            break;
          }
        }
        if (!found) transferList = [...transferList, buf.buffer];
      }
      return { message: buf, transfer: transferList };
    } catch (err) {
      // Falling back to the raw object is deliberate: if `JSON.stringify`
      // throws (a circular reference, a BigInt) the message is still
      // postable, because the transport structured-clones whatever it cannot
      // JSON-encode, and refusing it would break a working caller.
      //
      // What made this a *silent* protocol downgrade - and hid BUG-029 for so
      // long - is that nothing was reported. A framing failure in framed mode
      // means the worker will not see the envelope it is documented to
      // receive, so say so at the point it happens rather than letting it
      // surface much later as "unsupported protocol version" inside
      // `decodeMessage`, which points nowhere near the cause.
      this._debugLog?.(err, '_prepareForTransfer: could not frame, posting raw');
      // Every mode except `'legacy'` promises the worker an envelope it can
      // decode, so a framing failure is a broken promise in all three.
      if (this._messageCodec !== 'legacy') {
        this._logger?.warn?.(
          'PowerPool: message could not be framed and was posted unframed ' +
            `(messageCodec is "${this._messageCodec}"). A worker using ` +
            'decodeMessage() will reject it. Cause: ' +
            // `isError()` rather than `instanceof Error`, so a cross-realm failure
            // logs its own message instead of a stringified copy that carries the
            // class name too. WRK-007.
            (isError(err) ? err.message : String(err))
        );
      }
      return { message: msg, transfer: tr };
    }
  }

  /**
   * Decrement the global active task counter safely.
   * Ensures the counter never goes negative and centralizes error handling.
   *
   * **The `Math.max(0, …)` clamp is a mitigation, not a fix.** It stops the
   * counter going negative, but it cannot stop a *double* decrement from
   * counting as a single one, and that is the live hazard: `removeWorker`/
   * `resize`/`stopThePress` drain `workerObj.tasks` in one go, and a `message`
   * already in flight from a worker being terminated arrives afterwards and
   * decrements again. The count then falls below the number of tasks actually
   * running, so `getStats().activeTasks` under-reports, `_isIdle` can go true
   * while work is outstanding, and `drain()` resolves early against a pool that
   * is not idle.
   *
   * The real fix is per-task idempotency: hand each dispatched task a token
   * from a monotonic sequence, record it on the worker, and decrement only when
   * a completion actually consumes a token that was outstanding. A late message
   * then finds nothing to consume and is correctly ignored. This used to be
   * described by a `_taskTokenSeq` field on this class that nothing ever read,
   * which asserted a mechanism that did not exist; the field is gone and the
   * work is recorded as BUG-011 rather than implied to be done.
   *
   * @private
   * @param {number} [n=1]
   */
  _decrementActiveTasks(n = 1) {
    try {
      const dec = Number.isFinite(Number(n)) ? Math.max(0, Math.floor(Number(n))) : 1;
      this._activeTasks = Math.max(0, this._activeTasks - dec);
    } catch (err) {
      this._activeTasks = 0;
    }
  }

  /**
   * Resize the pool's maximum size at runtime.
   * If `n` is smaller than the current number of workers, extra workers
   * will be terminated (keeps at least `minSize`). If `n` is larger,
   * the pool may grow up to the new limit when demand increases.
   * @param {number} n - New maximum pool size.
   */
  resize(n) {
    // overload: resize(number) or resize({ minSize, maxSize })
    let newMin = this.minSize;
    let newMax = this.maxSize;
    if (n != null && typeof n === 'object') {
      if (Number.isFinite(n.minSize)) newMin = Math.max(0, Math.floor(n.minSize));
      if (Number.isFinite(n.maxSize)) newMax = Math.max(newMin, Math.floor(n.maxSize));
    } else {
      // numeric shorthand: set maxSize, keep minSize
      const v = Number(n);
      if (!Number.isFinite(v)) return;
      newMax = Math.max(newMin, Math.floor(v));
    }

    // apply new bounds
    this.minSize = Math.max(0, newMin);
    this.maxSize = Math.max(this.minSize, newMax);

    // If we need to grow to satisfy new minSize, create workers up to minSize (respecting maxSize)
    let added = 0;
    while (this.workers.length < this.minSize && this.workers.length < this.maxSize) {
      try {
        const before = this.workers.length;
        this._addWorkerInstance();
        if (this.workers.length === before) break;
        added++;
      } catch (err) {
        try {
          this._logger.error(err, 'resize: add worker failed');
        } catch (e) {
          this._debugLog?.(e, 'resize: logger.error failed');
        }
        try {
          this._bus.emit('pool:error', { phase: 'resize', error: err });
        } catch (e) {
          this._debugLog?.(e, 'resize: bus.emit failed');
        }
        break;
      }
    }

    // If we have more workers than the new max, terminate excess workers
    const terminatedIds = [];
    while (this.workers.length > this.maxSize) {
      const w = this.workers.pop();
      const id = this._terminateWorker(w, 'resize');
      if (id != null) terminatedIds.push(id);
    }

    // emit resize event/callback when workers were terminated or added
    if (terminatedIds.length || added) {
      const ev = {
        data: {
          type: 'pool:resize',
          terminated: terminatedIds,
          added,
        },
      };
      if (this._onresize) {
        try {
          this._onresize(ev);
        } catch (err) {
          this._logger.error(err, 'Pool onresize handler error');
        }
      }
      this._bus.emit('resize', ev);
      // also emit pool:scale with details about added/removed workers
      this._bus.emit('pool:scale', {
        added,
        terminated: terminatedIds,
        minSize: this.minSize,
        maxSize: this.maxSize,
      });
    }

    // Re-evaluate idle state after resizing
    this._updateIdleState();
  }

  /**
   * Create a new worker for this pool, wrapped for the current runtime.
   *
   * **This returns the `WorkerAgnostic` wrapper, not the raw native worker**
   * (WRK-004). It used to return `WorkerAgnostic.create(...)` — the class's
   * *static* helper, which resolves the source and hands back the bare native
   * worker — so the pool then wired `message`/`error`/`messageerror` itself,
   * with its own rule for pulling a payload out of an event. That left the
   * library with two event-normalisation implementations, and they disagreed
   * exactly where it mattered: the pool's rule was `e?.data !== undefined ?
   * e.data : e`, which is right for a browser `MessageEvent` and **wrong for
   * Node**, because `worker.on('message', value)` delivers the payload itself.
   * A worker replying with `{ data: rows, id: 7 }` therefore reached
   * `awaitResponse` as `rows` — every sibling field silently dropped, no error,
   * no counter. Verified against a real `worker_threads` worker; see
   * `test/powerPool.workerAgnostic.test.js`, which pins both runtimes.
   *
   * `WorkerAgnostic` has one rule and it is the right one in both: unwrap
   * `.data` only where the platform wraps a value in an event, and never on the
   * EventEmitter model, where there is no wrapper to unwrap.
   *
   * Creation still resolves the same way and still throws the same errors, so
   * the pool's own `workerSource` validation (and `WorkerAgnostic`'s) are
   * unchanged by this.
   *
   * @private
   * @returns {WorkerAgnostic} The wrapper; `.worker` is the raw native worker.
   * @throws {Error} When `workerSource` is invalid or worker construction fails.
   */
  _createWorkerInstance() {
    return new WorkerAgnostic(this._workerSource, {
      ...this._workerOptions,
      // `onError` is this library's own option, not the platform's, so it is
      // the pool's to fill in. See `_onWorkerListenerError` for why a worker
      // listener error goes to the logger and nowhere else.
      // Annotated here rather than only on `_onWorkerListenerError`: the implicit-any
      // is reported on this arrow's own parameters, so a JSDoc on the method alone
      // leaves it red.
      onError: (
        /** @type {*} */ err,
        /** @type {{type?: string, listener?: Function}} */ context
      ) => this._onWorkerListenerError(err, context),
    });
  }

  /**
   * Report a worker event handler that threw.
   *
   * The pool's own `message`/`error` handlers guard every caller-supplied
   * callback individually, so anything arriving here is a bug in this file
   * rather than in user code — an unhandled decode failure, a throw from a
   * capability announcement. It goes to the logger and the debug log and
   * nowhere else: **not** to `_bus.emit('pool:error')`, because this runs
   * *inside* the dispatch loop that emit would re-enter, and a second failure
   * inside error reporting is the one outcome worse than the original.
   *
   * Without a handler here the failure would be silent, which is the defect
   * WRK-003 recorded for this class: a listener that stops being called looks
   * exactly like a worker that went quiet.
   *
   * @param {*} err - What the handler threw.
   * @param {{type?: string, listener?: Function}} [context] - Which event.
   * @private
   * @returns {void}
   */
  _onWorkerListenerError(err, context) {
    this._logger.error(err, `worker ${context?.type ?? 'event'} handler failed`);
    this._debugLog?.(err, `_onWorkerListenerError: worker ${context?.type ?? 'event'}`);
  }

  _deleteWorkerUnderlyingMapping(workerObj) {
    try {
      const u = workerObj?.worker?._underlying;
      if (u && this._underlyingToWorkerObj) this._underlyingToWorkerObj.delete(u);
    } catch (e) {
      this._debugLog?.(e, '_deleteWorkerUnderlyingMapping failed');
    }
  }

  /**
   * Add and wire a new worker instance into the pool.
   *
   * This helper wraps the underlying worker instance with a small adapter
   * that encodes outgoing plain-object messages to transferable `Uint8Array`
   * when possible and decodes incoming binary messages back to objects.
   * It also wires cross-platform event handlers (`message`, `error`,
   * `messageerror`) and returns the `WorkerObj` metadata entry used by the pool.
   *
   * @private
   * @param {number} [id] - Optional explicit id for the worker entry.
   * @returns {WorkerObj} The newly created worker entry.
   */
  _addWorkerInstance(id) {
    if (id == null) id = this._nextWorkerId++;
    const agnostic = this._createWorkerInstance();
    // The raw native worker underneath the wrapper, and the `WorkerWrapper`
    // wraps **this** rather than the `WorkerAgnostic`. That is deliberate, not
    // incidental: the wrapper decides its own transfer list (an array *or* any
    // iterable or array-like, and it may add a buffer of its own encoding),
    // whereas `WorkerAgnostic.postMessage` normalises its argument down to an
    // array or a `{ transfer }` bag and would **drop** an array-like list on the
    // floor. Routing sends through the class would quietly stop transferring.
    // Events are the other way round: they are where the two runtimes disagree,
    // so they go through the class. See `_createWorkerInstance` (WRK-004).
    const underlying = agnostic.worker;

    const worker = new WorkerWrapper(underlying, this._logger, this);

    const workerObj = {
      id,
      worker,
      // The event-normalisation wrapper for this worker. Held so `_terminateWorker`
      // can release what it attached: `WorkerAgnostic.dispose()` detaches the
      // native listeners, and nothing else in the tree does. That method was added
      // by WRK-002 and this is its only in-repo consumer, which is why it went
      // unused: nothing that owned a worker ever called it. Without the call the
      // terminated native worker keeps a listener that closes over the pool, so a
      // pool that resized once stayed reachable from every worker it retired.
      _agnostic: agnostic,
      tasks: 0,
      lastActive: nowMs(),
      latencyEwma: null,
      _startTimes: new PowerQueue(),
      // What this worker has told the pool it can decode. Starts as "framed
      // only", which is what a worker that has never announced supports, so an
      // un-negotiated pool sends exactly what it sent before.
      protocol: { codecs: ['json'], native: false, announced: false },
      // Tasks this worker has finished over its lifetime, kept so a terminated
      // worker's output is not lost from `_terminatedWorkerTaskCountsTotal`.
      // Declared in the literal rather than assigned on the next line, which is
      // where it was: the two are the same at runtime, but a property added
      // after construction is absent from the type TypeScript infers here, so
      // every later `workerObj.completedTasks` read was an error against a shape
      // the code itself had just described.
      completedTasks: 0,
      // Set once this worker's in-flight tasks have been settled in bulk, so a
      // `message` that was already in flight when the worker was terminated does
      // not decrement the global counter a second time. See `_terminateWorker`
      // and the guard in the `onmessage` handler. BUG-011.
      tasksSettled: false,
    };
    this.workers.push(workerObj);
    this._totalWorkersCreated++;
    this._bus.emit('pool:scale', {
      action: 'add',
      id: workerObj.id,
      minSize: this.minSize,
      maxSize: this.maxSize,
    });
    // register underlying -> workerObj mapping so shared handlers can locate metadata
    try {
      this._underlyingToWorkerObj.set(underlying, workerObj);
    } catch (e) {
      /* ignore mapping failures */
    }

    // pool-level handler: decrements tasks, dispatches queued work and
    // forwards messages to pool listeners. This is assigned on the
    // wrapper `worker` so the underlying worker can forward a decoded
    // event into it.
    worker.onmessage = (e) => {
      const now = nowMs();
      // A late message from a worker whose tasks were already settled in bulk by
      // `_terminateWorker`. Its accounting is done; decrementing again is what
      // made the pool look idle while work was outstanding. The rest of the
      // handler still runs - the response may carry a `correlationId` that a
      // caller is awaiting, and dropping it would strand that promise.
      if (workerObj.tasksSettled) {
        this._debugLog?.(
          new Error('late message from a settled worker'),
          'ignoring decrement for already-settled worker'
        );
        return;
      }
      workerObj.tasks = Math.max(0, workerObj.tasks - 1);
      // decrement global active task count for the completed task
      this._decrementActiveTasks(1);
      workerObj.lastActive = now;

      // If the worker's response carries a correlationId, resolve any pending Promise.
      try {
        const data = e?.data;
        // The id can arrive on the payload (the framed path, and any worker that
        // echoes it the way the guides show) or on the event (a native envelope,
        // where the payload may be a Map, a typed array or a frozen object that
        // must not be written to).
        const cid = data && typeof data === 'object' ? data.correlationId : undefined;
        const key = cid != null ? cid : e?.correlationId;
        if (key != null) {
          const pid = String(key);
          const resp = Object.prototype.hasOwnProperty.call(data, 'response')
            ? data.response
            : data;
          this._cleanupPendingResponse(pid, { resolveWith: resp });
        }
      } catch (err) {
        this._debugLog?.(err, 'worker.onmessage: resolve pending response');
      }

      // Update EWMA latency using the oldest start timestamp for this worker if present
      try {
        const start = workerObj._startTimes?.length ? workerObj._startTimes.shift() : null;
        // Prefer worker-reported processing duration when available (worker may measure its own CPU time),
        // otherwise fall back to wall-clock latency computed from the recorded start time.
        let x = null;
        try {
          const data = e?.data;
          const dur = typeof data?.duration === 'number' ? data.duration : e?.duration;
          if (typeof dur === 'number' && Number.isFinite(dur)) {
            x = Math.max(0, Number(dur));
          } else if (start != null) {
            x = Math.max(0, now - start);
          }

          if (x != null) {
            // smoothing factor for per-worker EWMA; allow pool-level alpha when configured
            const alpha = this._autoScale?.alpha || 0.2;
            // Long-window RTT EWMA and a windowed minimum, for the
            // 'gradient2' and 'vegas' adaptive policies respectively. Both are
            // only maintained when one of those policies is active.
            if (this._autoScale && this._autoScale.policy !== 'ewma') {
              const longAlpha = this._autoScale.longWindowAlpha;
              if (this._longEwmaLatency == null) this._longEwmaLatency = x;
              else this._longEwmaLatency = longAlpha * x + (1 - longAlpha) * this._longEwmaLatency;
              if (x < this._minLatencyWindow) this._minLatencyWindow = x;
            }
            if (workerObj.latencyEwma == null) workerObj.latencyEwma = x;
            else workerObj.latencyEwma = alpha * x + (1 - alpha) * workerObj.latencyEwma;

            // update pool-level EWMA (aggregate) for autoscaling decisions
            if (this._ewmaLatency == null) this._ewmaLatency = x;
            else this._ewmaLatency = alpha * x + (1 - alpha) * this._ewmaLatency;

            // record pool-level performance metrics using worker-observed or computed task time
            // Update counts and Welford streaming stats (O(1) memory/time)
            this._totalTasksCompleted = (this._totalTasksCompleted || 0) + 1;
            workerObj.completedTasks = (workerObj.completedTasks || 0) + 1;
            // POOL-011. This was `const k = 1; // single sample`, read twice below.
            // A named constant for the literal 1 bought nothing: `k` had no second
            // value it could ever take, so every reader had to look up what `k` was
            // to learn it was one. The Welford recurrence is spelled with the literal
            // because that is what it is - and QUAL-008, which the row credits with
            // renaming it, left this one in place, so the row's premise was half
            // right about the wrong thing.
            const prevCount = this._taskDurationsWelfordCount;
            this._taskDurationsWelfordCount = prevCount + 1;
            const delta = x - this._taskDurationsWelfordMean;
            this._taskDurationsWelfordMean += delta / this._taskDurationsWelfordCount;
            const delta2 = x - this._taskDurationsWelfordMean;
            this._taskDurationsWelfordM2 += delta * delta2;
            if (x < this._taskDurationsMin) this._taskDurationsMin = x;
            if (x > this._taskDurationsMax) this._taskDurationsMax = x;
            if (Number.isFinite(this._slowTaskThreshold) && x > this._slowTaskThreshold) {
              this._slowTaskCount = (this._slowTaskCount || 0) + 1;
            }
          }
        } catch (err) {
          this._debugLog?.(err, 'worker.onmessage: latency tracking inner');
        }
      } catch (err) {
        this._debugLog?.(err, 'worker.onmessage: latency tracking outer');
      }

      // dispatch queued task if any, unless queue dispatch is paused for backpressure control
      if (
        !this._queuePaused &&
        this.queue.length > 0 &&
        workerObj.tasks < this._maxTasksPerWorker
      ) {
        let item;
        while (this.queue.length > 0) {
          item = this.queue.shiftHighestPriority((queuedItem) => {
            const priority = queuedItem.priority ?? 0;
            return this._priorityAgingMs > 0
              ? priority + Math.max(0, now - queuedItem.enqueuedAt) / this._priorityAgingMs
              : priority;
          });
          if (item.deadlineAt === undefined || item.deadlineAt > now) break;
          if (item.correlationId != null) {
            const err = new Error('postMessage queued task deadline elapsed');
            err.code = 'EDEADLINE';
            this._cleanupPendingResponse(item.correlationId, { rejectWith: err });
          }
          item = null;
        }
        if (item) {
          try {
            this._recordQueueWait(now - item.enqueuedAt);
            const dispatch = this._encodeForWorker(workerObj, item);
            this._dispatchToWorker(workerObj, dispatch, {
              correlationId: item.correlationId,
              startTime: now,
            });
          } catch (err) {
            this._debugLog?.(err, 'dispatch queued message to worker failed');
            this._logger.error(err, 'Failed to dispatch queued message to worker');
          }
        }
        // after removing one queued item, if we dropped below threshold clear the crossed flag
        if (this._queueHighCrossed && this.queue.length <= this._queueHighThreshold) {
          this._queueHighCrossed = false;
        }
      }

      if (this._onmessage) {
        try {
          this._onmessage(e);
        } catch (err) {
          this._logger.error(err, 'Pool onmessage handler error');
        }
      }
      this._bus.emit('message', e);

      // update idle state after processing a message (and possibly dispatching queued tasks)
      this._updateIdleState();
    };

    /**
     * Autoscale tick: simple policy that grows/shrinks by one worker based on
     * pool-level EWMA latency and queue pressure. Runs only when `autoScale`
     * is configured on the pool.
     *
     * - scale up: when EWMA > targetMs OR queue length exceeds worker count
     * - scale down: when EWMA < targetMs * 0.5 AND queue is empty
     */
    // forward underlying events, decoding binary payloads to JS objects
    /**
     * Handle a normalised `message` event from this worker's underlying Worker
     * and decode binary payloads back to JS values before forwarding to the
     * wrapper `worker.onmessage` handler.
     *
     * `event` is `WorkerAgnostic`'s `{ data, originalEvent }`, not the platform's
     * event: the class has already decided whether the value arrived wrapped in
     * a `MessageEvent` (browser) or bare (Node). The pool used to make that
     * decision itself, and got Node wrong — see `_createWorkerInstance`.
     *
     * @private
     * @param {{data: *, originalEvent: *}} event - The normalised event.
     */
    const _handleMessage = (event) => {
      // Already normalised, so there is no unwrapping here and no way for the two
      // runtimes to drift apart again.
      const data = event?.data;
      let decoded = data;
      /** @type {any} - the native envelope, when the reply arrived on that carrier */
      let inboundMeta = null;
      // A capability announcement is pool-internal protocol traffic: it is
      // consumed here and deliberately *not* forwarded to `message` listeners,
      // which never sent it and would have to recognise it to be correct. It is
      // also not a task, so it must not touch the task accounting below.
      if (isCapabilityAnnouncement(data)) {
        this._applyCapabilities(workerObj, data);
        return;
      }
      if (isNativeEnvelope(data)) {
        // The payload is unwrapped here so that nothing above this layer — user
        // `onmessage` handlers, correlation matching, latency sampling — has to
        // know which carrier a reply arrived on. Only `correlationId` and
        // `duration` are lifted, onto the event rather than onto the payload:
        // the payload belongs to the worker, and mutating it to carry pool
        // bookkeeping is the kind of thing that breaks on a frozen object.
        decoded = data.value;
        inboundMeta = data;
      }
      if (data && (data instanceof ArrayBuffer || ArrayBuffer.isView(data))) {
        try {
          if (this._messageCodec !== 'legacy') {
            // No sniffing: the envelope says what the payload is, so a binary
            // frame is handed over intact instead of being JSON.parse'd.
            decoded = decodeMessage(data).value;
          } else {
            decoded = u82o(data);
          }
        } catch (err) {
          try {
            _handleMessageError(err);
          } catch (ee) {
            this._debugLog?.(ee, '_handleMessage: _handleMessageError failed');
          }
          decoded = data;
        }
      }
      // When nothing was decoded, forward `WorkerAgnostic`'s object as it stands;
      // when the payload was unwrapped from a frame or an envelope, forward a new
      // one. Either way `correlationId`/`duration` land on **our** event object
      // rather than on the platform's, which the old code did by mutating a real
      // `MessageEvent` — a message that a browser may hand to more than one
      // listener. `originalEvent` is how a caller still reaches `origin`/`target`.
      // Typed rather than inferred: `correlationId`/`duration` are written onto
      // whichever object is forwarded, and `WorkerAgnostic`'s payload type has
      // only `data`/`originalEvent`, so an inferred type made both writes errors.
      /** @type {{data: *, originalEvent: *, correlationId?: string, duration?: number}} */
      const ev =
        decoded === data
          ? /** @type {*} */ (event)
          : {
              data: decoded,
              originalEvent: event && 'originalEvent' in event ? event.originalEvent : event,
            };
      if (inboundMeta) {
        // Pool bookkeeping the reply would otherwise lose. Read by correlation
        // matching and the latency sampler; see the comment at the unwrap above
        // for why these live on the event instead of on the payload.
        if (inboundMeta.correlationId != null) ev.correlationId = inboundMeta.correlationId;
        if (typeof inboundMeta.duration === 'number') ev.duration = inboundMeta.duration;
      }
      if (typeof worker.onmessage === 'function') {
        try {
          worker.onmessage(ev);
        } catch (err) {
          this._logger.error(err, 'worker wrapper onmessage error');
        }
      }
    };

    /**
     * Handle an error event from the underlying Worker and forward it to
     * the wrapper `worker.onerror` and pool-level error listeners.
     *
     * @private
     * @param {any} e - The error event or value.
     */
    const _handleError = (e) => {
      if (typeof worker.onerror === 'function') {
        try {
          worker.onerror(e);
        } catch (err) {
          this._logger.error(err, 'worker wrapper onerror error');
        }
      }
      // Pool-level `onerror` handler (see the `onerror` accessor). Kept in
      // step with `onmessage`/`onidle`: called for every worker error and
      // fully isolated so a throwing user handler cannot break the pool.
      if (typeof this._onerror === 'function') {
        try {
          this._onerror(e);
        } catch (err) {
          this._logger.error(err, 'pool onerror handler error');
        }
      }
      this._bus.emit('error', e);
    };

    /**
     * Handle a `messageerror` event from the underlying Worker and forward
     * it to the wrapper `worker.onmessageerror` and pool-level listeners.
     *
     * @private
     * @param {any} e - The messageerror event or value.
     */
    const _handleMessageError = (e) => {
      if (typeof worker.onmessageerror === 'function') {
        try {
          worker.onmessageerror(e);
        } catch (err) {
          this._logger.error(err, 'worker wrapper onmessageerror error');
        }
      }
      this._bus.emit('messageerror', e);
    };

    // Registration, and **not** attachment. The 51 lines this replaced picked a
    // native model by hand — `addEventListener`, else `.on`, else property
    // assignment — and `WorkerAgnostic._wireEvents` picks the same three, in the
    // same order, for the same reason. Two copies of that ladder is how the two
    // copies of the unwrap drifted apart in the first place (WRK-004), so the
    // ladder lives in the class now and the pool only says *which* events it
    // wants. `.on` and `.addEventListener` are aliases here, so the choice is
    // cosmetic; `.on` reads as "subscribe" and is what a Node-shaped caller
    // expects to see.
    //
    // `addEventListener` returns `this` and cannot throw for a non-function
    // handler, so none of these three calls is guarded the way the block above
    // guarded its nine — there was nothing to guard.
    agnostic.on('message', _handleMessage);
    agnostic.on('error', _handleError);
    agnostic.on('messageerror', _handleMessageError);

    return workerObj;
  }

  /**
   * Return the least-loaded worker (smallest `tasks` count).
   *
   * When multiple workers share the same `tasks` count prefer the one with
   * the lower EWMA latency (`latencyEwma`). Returns `null` when no workers
   * are available.
   *
   * @private
   * @returns {WorkerObj|null}
   */
  _findLeastLoadedWorker() {
    if (!this.workers.length) return null;
    let best = null;
    let bestTasks = Infinity;
    let bestLat = Number.POSITIVE_INFINITY;
    for (let i = 0; i < this.workers.length; i++) {
      const w = this.workers[i];
      const lat = w.latencyEwma != null ? w.latencyEwma : Number.POSITIVE_INFINITY;
      if (w.tasks < bestTasks || (w.tasks === bestTasks && lat < bestLat)) {
        best = w;
        bestTasks = w.tasks;
        bestLat = lat;
      }
    }
    return best;
  }

  /**
   * Determine whether a single-worker pool should queue rather than flood the
   * underlying worker with additional in-flight messages.
   * @private
   * @param {WorkerObj|null} least
   * @param {number|null} targetWorkerId
   * @returns {boolean}
   */
  /**
   * Claim an idempotency key, or report that it is already claimed.
   *
   * **In-flight versus settled is the decision this ledger exists to get right.**
   * A key is marked `in-flight` when the post is accepted for dispatch and moves
   * to `settled` once the task is on its way — so the two cases are
   * distinguishable, and both are refusals with different meanings:
   *
   * - `in-flight` means a **concurrent duplicate**: the first post has not been
   *   sent yet, so refusing is free and nothing has been applied twice.
   * - `settled` means a **retry**: the task was dispatched, may already have run,
   *   and refusing is the only thing standing between a caller retrying across a
   *   timeout and applying a side effect twice.
   *
   * Collapsing the two — one `seen` set, the usual shape — loses the ability to
   * say which happened, and it also loses the ability to release the key when a
   * post is refused before dispatch. `settled` carries a timestamp so the ledger
   * can expire it; `in-flight` does not, because an in-flight claim is released
   * by the post's own outcome rather than by time.
   *
   * @private
   * @param {string|number|undefined} key - `undefined` disables the ledger for
   *   this post.
   * @param {number} now - From `nowMs()`, so one post reads one clock.
   * @returns {boolean} `true` to proceed, `false` if the key is already claimed.
   */
  _idempotencyBegin(key, now) {
    // One lookup per posted message, counted whether or not a key was supplied.
    this._idempotencyLookups += 1;
    const ledger = this._idempotency;
    if (key === undefined || key === null || !ledger) return true;
    const k = String(key);
    // Bounded incremental expiry, run off the back of the lookup. Lazy expiry
    // alone would only ever clean keys that are looked up *again*, so a workload
    // of unique keys would grow the ledger without bound — and a ledger that
    // outlives its usefulness is a leak, which is why the settled state is a TTL
    // rather than a permanent mark.
    this._idempotencySweep(now);
    const existing = ledger.get(k);
    if (existing !== undefined) {
      if (existing.settledAt === null) this._idempotencyDuplicatesInFlight += 1;
      else this._idempotencyDuplicatesSettled += 1;
      return false;
    }
    // `settledAt: null` is the in-flight marker.
    ledger.set(k, { settledAt: null });
    this._idempotencySize = ledger.size;
    return true;
  }

  /**
   * Move a claimed key from in-flight to settled.
   *
   * @private
   * @param {string|number|undefined} key - Coerced with `String()`, as the pool
   *   coerces every idempotency key.
   * @param {number} now
   */
  _idempotencySettle(key, now) {
    if (key === undefined || key === null) return;
    // Narrowed into a local: `this._idempotency` is `Map | null` and `tsc` does
    // not carry a property-guard on `this` across statements, so every use below
    // would be a "possibly null" error. The guard is real — a settled key cannot
    // exist without a ledger — it just has to be expressed where the compiler can
    // see it.
    const ledger = this._idempotency;
    if (!ledger) return;
    const k = String(key);
    const entry = ledger.get(k);
    if (entry === undefined) return;
    entry.settledAt = now;
    this._idempotencySize = ledger.size;
  }

  /**
   * Drop a claim for a post that was never dispatched.
   *
   * @private
   * @param {string|number|undefined} key
   */
  _idempotencyRelease(key) {
    if (key === undefined || key === null) return;
    const ledger = this._idempotency;
    if (!ledger) return;
    ledger.delete(String(key));
    this._idempotencySize = ledger.size;
  }

  /**
   * Expire settled keys older than the TTL, examining a bounded slice per call.
   *
   * Bounded on purpose: an unbounded scan on the post path would make the cost of
   * opting in proportional to the size of the ledger, which is the opposite of
   * what the option is for. A rotating cursor means every entry is eventually
   * reached — the ledger drains at a bounded rate rather than never.
   *
   * `in-flight` entries are never expired. They are released by their post's own
   * outcome, and expiring one would let a still-running task be posted a second
   * time — the exact double-apply this feature is for.
   *
   * @private
   * @param {number} now
   */
  _idempotencySweep(now) {
    const ledger = this._idempotency;
    if (!ledger || ledger.size === 0) return;
    const ttl = this._idempotencyTtlMs;
    let examined = 0;
    for (const k of [...ledger.keys()]) {
      if (examined >= DEFAULT_IDEMPOTENCY_SWEEP_BATCH) break;
      examined += 1;
      const entry = ledger.get(k);
      if (entry && entry.settledAt !== null && now - entry.settledAt >= ttl) {
        ledger.delete(k);
        this._idempotencyExpired += 1;
      }
      if (examined >= ledger.size) break;
    }
    this._idempotencySize = ledger.size;
  }

  /**
   * Post a message to a worker in the pool.
   * The pool will try to reuse an idle/least-loaded worker, grow the pool
   * (up to `maxSize`), or queue the task if configured.
   *
   * @param {*} message - The message to post to a worker.
   * @param {Transferable[]=} transfer - Optional transfer list. If omitted and
   * a plain JS object is supplied, the pool will internally encode the object
   * to a transferable `Uint8Array` (via `o2u8`) and pass its `ArrayBuffer` as
   * the transfer list to avoid structured-clone copies.
   * @param {PostMessageOptions=} options - Optional flags controlling behavior such as `awaitResponse`, `timeout`, `workerId`, and `zeroCopy`.
   * @returns {boolean|Promise<any>} When `options.awaitResponse` is truthy this returns a `Promise` that resolves with the worker response; otherwise returns `true` when the message was accepted (dispatched or queued) or `false` when it was rejected.
   * @throws {Error} When `options.awaitResponse` is used but the provided `message` is not a plain object.
   */
  postMessage(message, transfer, options) {
    // POOL-013. The ledger is consulted *outside* `_postMessageInner` rather than
    // inside it, so this wrapper sees exactly one thing the inner method cannot
    // tell it: whether the task was accepted. Every one of the inner method's
    // return paths — dispatched, queued, grown-into, `false`, a pending response
    // promise — funnels through here, so the settle/release pair cannot be missed
    // on one of them. That matters: a key left `in-flight` by a rejected post
    // would block every retry of a task that never ran.
    //
    // The counter is incremented even when the post carries no key, and that is
    // deliberate. The cost being paid for is *a Map lookup per posted message*,
    // and the only honest way to report it is lookups ÷ posts — which requires the
    // no-key case to be counted too. A counter that only moved for keyed posts
    // would make the feature look free for the traffic that opts out of it.
    if (!this._idempotency) return this._postMessageInner(message, transfer, options);
    const now = nowMs();
    const key = options?.idempotencyKey;
    if (!this._idempotencyBegin(key, now)) return false;
    let result;
    try {
      result = this._postMessageInner(message, transfer, options);
    } catch (err) {
      this._idempotencyRelease(key);
      throw err;
    }
    // `false` is the inner method's "refused" answer: the pool is shut down, a
    // targeted worker is missing or busy, the queue is full and `drop-oldest`
    // dropped it, or `rejectOversized` rejected it. None of those ran the task,
    // so the key must not stay in the ledger — a caller retrying after a
    // rejection has to be allowed to try again.
    if (result === false) this._idempotencyRelease(key);
    // Anything else was accepted: dispatched, queued, or a pending-response
    // promise for a task already on its way. Settled, including for the promise,
    // because that is precisely the case this ledger exists for — a caller that
    // timed out waiting for a response and retried. The task is very likely
    // running; refusing the retry is the whole point.
    else this._idempotencySettle(key, now);
    return result;
  }

  /**
   * Post a message and wait for its worker response.
   *
   * @param {*} message - The message to post to a worker.
   * @param {(PostMessageOptions & {transfer?: TransferList})=} options - Request options.
   * @returns {Promise<any>} The response from the worker.
   */
  request(message, options) {
    const { transfer, ...postOptions } = options ?? {};
    return this.postMessage(message, transfer, {
      ...postOptions,
      awaitResponse: true,
    });
  }

  /**
   * `postMessage` without the POOL-013 ledger wrapper.
   *
   * Split out so the ledger sees one return value per post rather than the eight
   * the decision is spread across, and so the settled/release pair cannot be
   * forgotten on one path.
   *
   * @private
   * @param {*} message
   * @param {Transferable[]=} transfer
   * @param {PostMessageOptions=} options
   * @returns {boolean|Promise<any>}
   */
  _postMessageInner(message, transfer, options) {
    // A shut-down pool is final: refuse to dispatch rather than silently
    // re-growing the pool (which previously created a worker with no reaper
    // interval, pinning the Node.js process forever).
    this._assertNotTerminated();
    // support optional third-argument `options` for Promise-based responses
    options = options || undefined;
    // capture a single timestamp for this dispatch to avoid multiple syscalls
    const now = nowMs();
    if (options?.deadlineAt !== undefined && !Number.isFinite(options.deadlineAt)) {
      throw new TypeError('postMessage deadlineAt must be finite');
    }
    // support explicit per-worker targeting via `options.workerId`
    const targetWorkerId = options?.workerId != null ? options.workerId : null;
    const singleWorkerDirectFastPath =
      targetWorkerId == null && this.workers.length === 1 && this._maxTasksPerWorker === Infinity;
    // prefer an existing idle/least-loaded worker
    const least =
      targetWorkerId != null
        ? this.workers.find((w) => w.id === targetWorkerId)
        : singleWorkerDirectFastPath
          ? this.workers[0]
          : this._findLeastLoadedWorker();

    // support awaiting a response: options.awaitResponse or explicit options.correlationId
    const wantResponse = Boolean(options?.awaitResponse || options?.correlationId != null);
    let correlationId;
    let pendingPromise;
    if (wantResponse) {
      // Bound the correlation id to 32 bits to avoid unbounded integer growth
      // in extremely long-lived pools. Use unsigned 32-bit wrap-around.
      correlationId =
        options.correlationId != null
          ? String(options.correlationId)
          : this._generateCorrelationId();
      // only plain-object messages can be augmented with correlationId
      const isPlainObject =
        message !== null &&
        typeof message === 'object' &&
        !ArrayBuffer.isView(message) &&
        !(message instanceof ArrayBuffer);
      if (!isPlainObject) {
        throw new Error('postMessage awaitResponse requires a plain-object message');
      }
      // attach correlation id to the outgoing message
      // (workers should echo this field back in their response)
      message = Object.assign({}, message, { correlationId });

      const created = this._createPendingResponsePromise(correlationId, options);
      pendingPromise = created.pendingPromise;
      correlationId = created.correlationKey;
    }
    if (options?.deadlineAt !== undefined && options.deadlineAt <= now) {
      const err = new Error('postMessage deadline elapsed');
      err.code = 'EDEADLINE';
      if (wantResponse && correlationId) {
        this._cleanupPendingResponse(correlationId, { rejectWith: err });
        return pendingPromise;
      }
      return false;
    }

    const adaptiveLimit =
      this._autoScale?.policy && this._autoScale.policy !== 'ewma'
        ? Math.max(1, Math.ceil(this._adaptiveLimit))
        : null;
    if (adaptiveLimit !== null && this._activeTasks >= adaptiveLimit) {
      if (this.taskQueueEnabled) {
        const prepared = this._prepareForTransfer(message, transfer, options);
        return this._enqueueOrReject(
          prepared,
          wantResponse,
          correlationId,
          pendingPromise,
          options
        );
      }
      if (wantResponse && correlationId) {
        this._cleanupPendingResponse(correlationId, {
          rejectWith: new Error('adaptive concurrency limit reached'),
        });
        return pendingPromise;
      }
      return false;
    }

    // (moved to class method `_prepareForTransfer`) use that instead

    if (least?.tasks < this._maxTasksPerWorker) {
      try {
        const startTime = now;
        const prepared = this._prepareForTransfer(message, transfer, options);
        return this._postToWorkerObj(
          least,
          prepared,
          startTime,
          wantResponse,
          correlationId,
          pendingPromise
        );
      } catch (err) {
        if (wantResponse && correlationId) {
          try {
            this._cleanupPendingResponse(correlationId, { rejectWith: err });
          } catch (e) {
            this._debugLog?.(e, 'postMessage: cleanupPendingResponse failed');
          }
          try {
            this._logger.error(err, 'Failed to postMessage to worker');
          } catch (e) {
            this._debugLog?.(e, 'postMessage: logger.error failed');
          }
          return pendingPromise;
        }
        try {
          this._logger.error(err, 'Failed to postMessage to worker');
        } catch (e) {
          this._debugLog?.(e, 'postMessage: logger.error failed');
        }
        return false;
      }
    }

    // If a specific workerId was requested but we didn't dispatch above,
    // fail fast: the targeted worker is missing or at capacity.
    if (targetWorkerId != null && (!least || least.tasks >= this._maxTasksPerWorker)) {
      if (wantResponse && correlationId) {
        try {
          this._cleanupPendingResponse(correlationId, {
            rejectWith: new Error('targeted worker unavailable'),
          });
        } catch (e) {
          this._debugLog?.(e, 'postMessage: cleanupPendingResponse failed');
        }
        return pendingPromise;
      }
      return false;
    }

    // if we can grow the pool, create a new worker and use it
    // If a specific workerId was requested, do not auto-grow the pool to satisfy it
    if (targetWorkerId == null && this.workers.length < this.maxSize) {
      const startTime = now;
      return this._tryGrowPool(
        message,
        transfer,
        options,
        startTime,
        wantResponse,
        correlationId,
        pendingPromise
      );
    }

    // pool full and all workers at capacity (or targeted worker busy/missing)
    if (this.taskQueueEnabled) {
      const prepared = this._prepareForTransfer(message, transfer, options);
      return this._enqueueOrReject(prepared, wantResponse, correlationId, pendingPromise, options);
    }

    // fallback: round-robin dispatch. Use modulo to keep `_nextIndex` bounded
    if (!this.workers.length) return wantResponse ? pendingPromise : false;
    const idx = this._nextIndex % this.workers.length;
    // advance and wrap to avoid unbounded integer growth
    this._nextIndex = (this._nextIndex + 1) % this.workers.length;
    const fallback = this.workers[idx];
    try {
      const startTime = now;
      const prepared = this._prepareForTransfer(message, transfer, options);
      return this._postToWorkerObj(
        fallback,
        prepared,
        startTime,
        wantResponse,
        correlationId,
        pendingPromise
      );
    } catch (err) {
      if (wantResponse && correlationId) {
        try {
          this._cleanupPendingResponse(correlationId, { rejectWith: err });
        } catch (e) {
          this._debugLog?.(e, 'postMessage: cleanupPendingResponse failed');
        }
        try {
          this._logger.error(err, 'Failed to postMessage to fallback worker');
        } catch (e) {
          this._debugLog?.(e, 'postMessage: logger.error failed');
        }
        return pendingPromise;
      }
      try {
        this._logger.error(err, 'Failed to postMessage to fallback worker');
      } catch (e) {
        this._debugLog?.(e, 'postMessage: logger.error failed');
      }
      return false;
    }
  }

  /**
   * Generate a correlation id for a pending response.
   *
   * Shape is `<processTag>-<sequence>`, both base 36. The sequence is
   * monotonic for the whole **process**, not for the pool, so ids are unique
   * across every pool in it - which subsumes uniqueness within one pool, the
   * only matching that actually happens (a response arriving at the pool that
   * sent it, looked up in that pool's pending map). The process tag exists so
   * two processes sharing a log do not produce identical ids, and costs one
   * `Math.random` for the whole process rather than one per message.
   *
   * A per-pool counter with a shared tag is *not* sufficient: two pools both
   * emit `<tag>-0`. That was the first version of this change and its own test
   * caught it.
   *
   * This replaced `crypto.randomUUID()` (PERF-002), which was ~7.7x slower
   * per id and produced ids more than four times longer. `randomUUID` buys
   * cross-process uniqueness, which correlation matching does not need; the
   * process tag buys it for free at the cost of one allocation. Measured over
   * 200k ids: 0.163 us -> 0.021 us, 42 chars -> 10.
   *
   * @private
   * @returns {string}
   */
  _generateCorrelationId() {
    return `${CORRELATION_PROCESS_TAG}-${(_correlationSequence++).toString(36)}`;
  }

  /**
   * Centralized cleanup for a pending response entry.
   * Ensures the timer is cleared and the entry is resolved/rejected exactly once.
   * @private
   * @param {string|number} key
   * @param {{resolveWith?:any, rejectWith?:any}} opts
   */
  _cleanupPendingResponse(key, opts = {}) {
    const k = key != null ? String(key) : key;
    const entry = this._pendingResponses.get(k);
    if (!entry) return false;
    try {
      if (entry.timer) {
        try {
          clearTimeout(entry.timer);
        } catch (e) {
          this._debugLog?.(e, '_cleanupPendingResponse: clearTimeout failed');
        }
      }
    } catch (e) {
      this._debugLog?.(e, '_cleanupPendingResponse: timer check failed');
    }
    try {
      if (Object.prototype.hasOwnProperty.call(opts, 'resolveWith'))
        entry.resolve(opts.resolveWith);
      else if (Object.prototype.hasOwnProperty.call(opts, 'rejectWith'))
        entry.reject(opts.rejectWith);
    } catch (e) {
      this._debugLog?.(e, '_cleanupPendingResponse: resolve/reject failed');
    } finally {
      try {
        this._pendingResponses.delete(k);
      } catch (e) {
        this._debugLog?.(e, '_cleanupPendingResponse: delete failed');
      }
    }
    return true;
  }

  /**
   * Broadcasts a message to all workers in the pool.
   * @param {*} message
   * @param {Transferable[]=} transfer - Optional transfer list. If omitted and a
   * plain JS object is supplied, the pool will attempt to encode the object for
   * each worker into a transferable `Uint8Array` (via `o2u8`) so each worker
   * receives an independent transferable buffer to avoid structured-clone copies.
   * @returns {void}
   */
  broadcast(message, transfer) {
    // Snapshot the time once for this broadcast to avoid multiple syscalls
    // and to keep `lastActive` consistent across all workers in this broadcast.
    const now = nowMs();
    // If a plain object and no transfer supplied, encode once and reuse the encoded
    // payload for each worker (slice per-worker to create transferable buffers).
    let sharedU8 = null;
    const isPlainObject =
      message !== null &&
      typeof message === 'object' &&
      !ArrayBuffer.isView(message) &&
      !(message instanceof ArrayBuffer);
    for (const w of this.workers) {
      try {
        let msg = message;
        let tr = transfer;
        if (!tr && isPlainObject) {
          try {
            if (sharedU8 == null) sharedU8 = this._encodeForTransfer(message);
            // create a per-worker copy of the encoded data (slice creates a new ArrayBuffer)
            const copy = sharedU8.slice();
            msg = copy;
            tr = [copy.buffer];
          } catch (err) {
            msg = message;
            tr = undefined;
          }
        }
        // One timestamp for the whole broadcast, so every record shares it.
        this._dispatchToWorker(w, { message: msg, transfer: tr }, { startTime: now });
      } catch (err) {
        this._logger.error(err, 'broadcast error');
      }
    }
    this._updateIdleState();
  }

  /**
   * Normalize stop-the-press options and strip internal-only flags.
   * @private
   * @param {{recreateWorkers?: boolean}&PostMessageOptions=} options
   * @returns {{recreate: boolean, fwdOptions: Object|undefined}}
   */
  _normalizeStopThePressOptions(options) {
    const recreate =
      typeof options?.recreateWorkers !== 'undefined' ? Boolean(options.recreateWorkers) : true;
    const fwdOptions = typeof options === 'object' ? Object.assign({}, options) : undefined;
    if (fwdOptions) delete fwdOptions.recreateWorkers;
    return { recreate, fwdOptions };
  }

  /**
   * Shared reset routine used by stop-the-press APIs.
   * Clears queue and pending responses, terminates workers, optionally recreates workers,
   * and updates idle state.
   * @private
   * @param {{recreate:boolean, scope:string}} config
   * @returns {{currentCount:number, terminatedIds:number[]}}
   */
  _resetPoolForStopThePress({ recreate, scope }) {
    try {
      if (typeof this.queue?.clear === 'function') this.queue.clear();
    } catch (err) {
      this._logger.error(err, `${scope}: failed to clear queue`);
    }
    // Reset queue high-watermark state when queue is cleared to avoid stale flags
    try {
      this._queueHighCrossed = false;
    } catch (e) {
      this._debugLog?.(e, '_resetPoolForStopThePress: queueHighCrossed reset failed');
    }

    try {
      for (const [cid] of this._pendingResponses) {
        try {
          this._cleanupPendingResponse(cid, {
            rejectWith: new Error(`${scope}: cancelled pending response`),
          });
        } catch (e) {
          this._debugLog?.(e, '_resetPoolForStopThePress: cleanupPendingResponse failed');
        }
      }
    } catch (err) {
      this._logger.error(err, `${scope}: failed to cancel pending responses`);
    }

    let currentCount;
    let workersList;
    try {
      const workersRef = this.workers;
      currentCount = Number(workersRef?.length) || 0;
      if (Array.isArray(workersRef)) {
        workersList = workersRef.slice();
      } else {
        workersList = new Array(currentCount);
        for (let i = 0; i < currentCount; i++) workersList[i] = workersRef[i];
      }
    } catch (err) {
      this._logger.error(err, `${scope}: failed to snapshot workers`);
      currentCount = 0;
      workersList = [];
    }
    const terminatedIds = workersList.map((w) => w?.id).filter((x) => x != null);
    try {
      for (let i = workersList.length - 1; i >= 0; i--) {
        const w = workersList[i];
        const id = this._terminateWorker(w, `${scope}:reset`);
        if (id != null) terminatedIds.push(id);
      }
      this.workers.length = 0;
      this._activeTasks = 0;
    } catch (err) {
      this._logger.error(err, `${scope}: failed while terminating workers`);
    }

    if (!recreate) {
      this._clearLifecycleIntervals();
    }

    if (recreate) {
      const desired = Math.max(this.minSize, Math.min(currentCount, this.maxSize));
      for (let i = 0; i < desired; i++) {
        try {
          const before = this.workers.length;
          this._addWorkerInstance();
          if (this.workers.length === before) break;
        } catch (err) {
          try {
            this._logger.error(err, 'recreate: add worker failed');
          } catch (e) {
            this._debugLog?.(e, 'recreate: logger.error failed');
          }
          try {
            this._bus.emit('pool:error', { phase: 'recreate', error: err });
          } catch (e) {
            this._debugLog?.(e, 'recreate: bus.emit failed');
          }
          break;
        }
      }
      try {
        this._ensureReaper();
      } catch (e) {
        this._debugLog?.(e, 'recreate: ensureReaper failed');
      }
    }

    this._updateIdleState();
    return { currentCount, terminatedIds };
  }

  /**
   * Stop all pending queued tasks and immediately post a message to the pool.
   * This clears the internal task queue first (cancelling pending tasks),
   * updates the pool idle state, then forwards the provided message using
   * `postMessage` so the message is dispatched to a live worker immediately
   * (or enqueued if no worker can accept it).
   *
   * @param {*} message - The message to post after clearing pending tasks.
   * @param {Transferable[]=} transfer - Optional transfer list. When omitted
   * and a plain object is supplied, the pool will attempt to encode the
   * object to a transferable `Uint8Array` for efficient transfer.
   * @param {Object=} options - Optional options forwarded to `postMessage`.
   * @returns {boolean|Promise<any>} The same return value as `postMessage`.
   */
  stopThePress(message, transfer, options) {
    const { recreate, fwdOptions } = this._normalizeStopThePressOptions(options);
    const { currentCount, terminatedIds } = this._resetPoolForStopThePress({
      recreate,
      scope: 'stopThePress',
    });

    // emit pool:scale for the mass-termination (if any)
    try {
      if (terminatedIds?.length) {
        this._bus.emit('pool:scale', {
          action: 'remove',
          terminated: terminatedIds,
          count: currentCount,
        });
      }
    } catch (e) {
      this._logger.error(e, 'pool scale stopThePress listener error');
    }

    // 4) finally forward the provided message using normal dispatch.
    //    When the caller explicitly opted out of worker recreation there is
    //    nothing to dispatch to: forwarding would immediately grow the pool
    //    again and defeat `recreateWorkers: false`, so only the queue is
    //    restored (and the message enqueued for a future `addWorker()`).
    if (!recreate) {
      // The documented contract is "the same return value as `postMessage`", so
      // the enqueue result is forwarded rather than an unconditional `true`.
      // This is what makes `maxQueueLength` observable here: with a full queue
      // the message is refused and the caller is told so, instead of `stopThePress`
      // reporting a success that discarded the message it was handed.
      try {
        // Prepare it first, exactly as `postMessage` does. This used to enqueue
        // `{ message, transfer }` straight from the caller's arguments, which
        // skipped `_prepareForTransfer` entirely — and that is the whole method:
        // under `messageCodec: 'negotiated'` the carrier is a *per-worker*
        // decision, so an item the drain finds without `deferred` gets encoded
        // for a worker that may not want it. Measured, with the pool full and
        // one task in flight:
        //
        //     codec=negotiated   postMessage  -> message, transfer, deferred
        //     codec=negotiated   stopThePress -> message, transfer          <-- no marker
        //
        // One line, and the two routes stop disagreeing about what an item in the
        // queue is.
        return this._enqueueOrReject(
          this._prepareForTransfer(message, transfer, options),
          false,
          undefined,
          undefined,
          options
        );
      } catch (e) {
        this._logger.error(e, 'stopThePress: enqueue after reset failed');
        return false;
      }
    }
    return this.postMessage(message, transfer, fwdOptions);
  }

  /**
   * Post a batch of messages to the pool.
   * Each entry is an object: `{ message, transfer? }`.
   * Returns an array with the same length as `items` where each element is
   * either a boolean (accepted) or a Promise (when `options.awaitResponse` is used).
   * @param {{message:*,transfer?:Transferable[]}[]} items
   * @param {PostMessageOptions&{correlationIdFactory?: function(number): (string|number)}=} options - Optional options forwarded to each `postMessage` call.
   * @returns {(boolean|Promise<any>)[]}
   * @throws {Error} When `items` is not an array.
   */
  postMessageBatch(items, options) {
    this._assertNotTerminated();
    // One timestamp for the whole batch, as `postMessage` and `broadcast`
    // already do. `_dispatchToWorker` defaults `startTime` to `nowMs()`, so
    // without this every item in the batch paid a syscall — and the loops below
    // call it per item, so a batch of N cost N clock reads. `startTime` is the
    // task's start for `lastActive` and `_startTimes`, and a batch dispatches
    // its items at the same moment, so one read is accurate to within the
    // batch's own duration rather than wrong.
    const now = nowMs();
    if (!Array.isArray(items))
      throw new Error('postMessageBatch expects an array of {message, transfer?}');

    // If the caller expects per-item responses (awaitResponse or explicit correlationId),
    // defer to the single-item `postMessage` implementation so correlation ids and
    // pending Promises are handled exactly the same way for each item.
    const wantsResponse = Boolean(options?.awaitResponse || options?.correlationId != null);
    const correlationIdFactory =
      typeof options?.correlationIdFactory === 'function' ? options.correlationIdFactory : null;
    if (wantsResponse) {
      if (options?.correlationId != null && items.length > 1 && !correlationIdFactory) {
        throw new Error(
          'postMessageBatch cannot use a fixed correlationId for multiple items; provide options.correlationIdFactory or omit correlationId'
        );
      }
      // A `correlationIdFactory` is caller code, and a caller-supplied factory
      // is the one place a duplicate id can be produced *by the batch itself*.
      // `postMessage` does not defend against this: a second registration
      // under a live key rejects the first waiter with
      // `ERR_POOL_DUPLICATE_CORRELATION_ID` and takes over the key, so a
      // 3-item batch with a constant factory would leave caller 1 holding a
      // promise that is already rejected and the last result resolving for
      // everyone. Worse, it is destructive *and* partial - the first two
      // messages were already dispatched before the third collided.
      //
      // So the ids are resolved once, up front, and validated as a set before
      // a single item is dispatched. A duplicate then fails the whole call
      // atomically, with nothing sent and nothing orphaned. Resolving once
      // also means the factory is called exactly `items.length` times even for
      // an impure factory - the ids it produced are the ids that get used.
      const ids = correlationIdFactory
        ? this._resolveBatchCorrelationIds(items, correlationIdFactory)
        : null;
      const results = new Array(items.length);
      for (let i = 0; i < items.length; i++) {
        const it = items[i] || {};
        const perItemOptions = Object.assign({}, options);
        if (ids) perItemOptions.correlationId = ids[i];
        results[i] = this.postMessage(it.message, it.transfer, perItemOptions);
      }
      return results;
    }

    // Optimized path for fire-and-forget batches (no per-item Promise handling):
    // - prepare transferable buffers once per item (avoid repeated structured-clone attempts)
    // - attempt direct dispatch to available workers
    // - collect any prepared items that must be queued and push them into the queue
    const results = new Array(items.length);
    const queuedPrepared = [];
    const targetWorkerId = options?.workerId != null ? options.workerId : null;

    // `clone` deliberately left at its default (false): the per-message
    // `u8.slice()` it avoids is the expensive half of this path, not the cheap
    // one - measured at ~1385 ns of a ~2942 ns message against ~1557 ns without
    // it, because the copy it dodges is a *native* structured-clone copy while
    // the slice is an interpreted `memcpy`. See `prepareBuffers`.
    const preparedItems = this.prepareBuffers(items, {
      zeroCopy: Boolean(options?.zeroCopy),
    });
    const adaptiveLimit =
      this._autoScale?.policy && this._autoScale.policy !== 'ewma'
        ? Math.max(1, Math.ceil(this._adaptiveLimit))
        : null;
    let adaptiveSlots =
      adaptiveLimit === null
        ? Number.POSITIVE_INFINITY
        : Math.max(0, adaptiveLimit - this._activeTasks);

    // Single-worker opt-in fast path: avoid repeated worker selection and
    // queueing overhead when there is only one worker and it can accept
    // unlimited tasks via the native worker queue.
    if (
      targetWorkerId == null &&
      this.workers.length === 1 &&
      this._maxTasksPerWorker === Infinity &&
      adaptiveLimit === null
    ) {
      const obj = this.workers[0];
      let idleStateDirty = false;
      for (let i = 0; i < items.length; i += 1) {
        const prepared = preparedItems[i] || {
          message: items[i]?.message,
          transfer: items[i]?.transfer,
        };
        try {
          // `_dispatchToWorker` resolves a deferred encode, so this branch no
          // longer speaks a different protocol from `postMessage` — which is how
          // it used to fail every batched request.
          this._dispatchToWorker(obj, prepared, { startTime: now });
          idleStateDirty = true;
          results[i] = true;
        } catch (err) {
          results[i] = this._reportPostFailure(err, 'postMessageBatch:single-worker');
        }
      }
      if (idleStateDirty) this._updateIdleState();
      return results;
    }

    const isTargeted = targetWorkerId != null;
    let chosen;
    if (isTargeted) {
      chosen = this.workers.find((w) => w.id === targetWorkerId);
      if (!chosen) return items.map(() => false);
    } else {
      chosen = this._findLeastLoadedWorker();
    }
    let idleStateDirty = false;

    for (let i = 0; i < items.length; i++) {
      const it = items[i] || {};
      const prepared = preparedItems[i] || { message: it.message, transfer: it.transfer };
      let dispatched = false;

      if (adaptiveSlots <= 0) {
        if (this.taskQueueEnabled) {
          queuedPrepared.push({
            message: prepared.message,
            transfer: prepared.transfer,
            index: i,
            priority: options?.priority ?? 0,
          });
          results[i] = true;
        } else {
          results[i] = false;
        }
        continue;
      }

      // If chosen worker is saturated, clear it so we re-select on demand
      if (chosen?.tasks >= this._maxTasksPerWorker) chosen = null;

      // try to reuse the same worker choice until it becomes saturated
      let least = chosen;
      if (!least && !isTargeted) least = this._findLeastLoadedWorker();

      if (least?.tasks < this._maxTasksPerWorker) {
        try {
          this._dispatchToWorker(least, prepared, { startTime: now });
          idleStateDirty = true;
          results[i] = true;
          dispatched = true;
          adaptiveSlots--;
          // keep using this worker until it becomes saturated
          chosen = least.tasks < this._maxTasksPerWorker ? least : null;
        } catch (err) {
          results[i] = this._reportPostFailure(err, 'postMessageBatch:dispatch');
          dispatched = true;
        }
      }

      if (!dispatched) {
        // If we can grow the pool (and no specific workerId was requested), create a new worker and use it
        if (targetWorkerId == null && this.workers.length < this.maxSize) {
          try {
            const obj = this._addWorkerInstance();
            if (!obj) {
              results[i] = false;
              dispatched = true;
            } else {
              this._dispatchToWorker(obj, prepared, { startTime: now });
              idleStateDirty = true;
              results[i] = true;
              dispatched = true;
              adaptiveSlots--;
              // prefer using the newly-created worker for next items
              chosen = obj.tasks < this._maxTasksPerWorker ? obj : null;
            }
          } catch (err) {
            results[i] = this._reportPostFailure(err, 'postMessageBatch:add-worker');
            dispatched = true;
          }
        }
      }

      if (!dispatched) {
        if (targetWorkerId != null) {
          // targeted worker semantics are fail-fast when busy or missing
          results[i] = false;
          continue;
        }

        // Pool is saturated: collect for queueing or fallback
        if (this.taskQueueEnabled) {
          const policy = this._queuePolicy;
          if (policy === 'reject' || (policy === 'drop-newest' && this.queue.length > 0)) {
            results[i] = false;
          } else {
            if (policy === 'drop-oldest' && this.queue.length > 0) {
              const dropped = this.queue.shift();
              if (dropped?.correlationId != null) {
                this._cleanupPendingResponse(dropped.correlationId, {
                  rejectWith: new Error('postMessage queued task dropped by policy'),
                });
              }
            }
            queuedPrepared.push({
              message: prepared.message,
              transfer: prepared.transfer,
              index: i,
              priority: options?.priority ?? 0,
            });
            results[i] = true;
          }
        } else {
          // fallback round-robin
          if (!this.workers.length) {
            results[i] = false;
          } else {
            const idx = this._nextIndex % this.workers.length;
            this._nextIndex = (this._nextIndex + 1) % this.workers.length;
            const fallback = this.workers[idx];
            try {
              this._dispatchToWorker(fallback, prepared, { startTime: now });
              idleStateDirty = true;
              results[i] = true;
              adaptiveSlots--;
            } catch (err) {
              results[i] = false;
              this._logger.error(err, 'Failed to postMessage to fallback worker');
            }
          }
        }
      }
    }

    // Push queued items into the queue using batch enqueue for efficiency
    if (queuedPrepared.length) {
      try {
        // A batch can overshoot `maxQueueLength` in one go, so reserve room for
        // the whole group up front rather than pushing the overflow and then
        // noticing. The items that do not fit are refused - the newest ones,
        // because that is what every policy except `drop-oldest` already does.
        const admitted = this._reserveQueueSlots(queuedPrepared.length);
        if (admitted < queuedPrepared.length) {
          for (let i = admitted; i < queuedPrepared.length; i++) {
            results[queuedPrepared[i].index] = false;
          }
          queuedPrepared.length = admitted;
        }
        if (!queuedPrepared.length) {
          this._logger.error?.(
            new Error(
              `postMessageBatch rejected ${items.length - admitted} task(s): task queue is full (maxQueueLength ${this._maxQueueLength})`
            ),
            'postMessageBatch: queue full'
          );
        } else {
          // queue stores plain objects `{message,transfer}` so we can pass the array directly
          const enqueuedAt = nowMs();
          for (const item of queuedPrepared) item.enqueuedAt = enqueuedAt;
          this.queue.pushMany(queuedPrepared);
          idleStateDirty = true;
          // emit queue high-watermark event when threshold crossed (avoid spamming)
          try {
            if (
              Number.isFinite(this._queueHighThreshold) &&
              this.queue.length > this._queueHighThreshold &&
              !this._queueHighCrossed
            ) {
              this._queueHighCrossed = true;
              this._bus.emit('pool:queue:high', {
                length: this.queue.length,
                threshold: this._queueHighThreshold,
              });
            }
          } catch (e) {
            this._debugLog?.(e, 'postMessageBatch: bus.emit pool:queue:high failed');
          }
        }
      } catch (err) {
        this._logger.error(err, 'postMessageBatch: failed to enqueue prepared items');
      }
    }

    // Update idle state once for the whole batch if anything changed
    if (idleStateDirty) this._updateIdleState();

    return results;
  }

  /**
   * Stop the press and then post a batch of messages.
   *
   * Clears the internal task queue and terminates inflight workers (optionally recreating them),
   * rejects pending response Promises, then forwards the provided batch to `postMessageBatch`.
   *
   * This method mirrors the semantics of `stopThePress` for single messages but
   * operates on a batch. Use it when you need to atomically cancel pending work
   * and then seed the pool with a new set of tasks.
   *
   * @param {{message:*,transfer?:Transferable[]}[]} items - Array of items to send after clearing the pool.
   * @param {Object=} options - Optional options forwarded to `postMessageBatch`.
   *   Recognized options include:
   *     - `recreateWorkers` (boolean, default: true) — whether to recreate replacement workers after termination.
   *     - `awaitResponse` (boolean) — if true, returned slots will be Promises as in `postMessageBatch`.
   *     - `workerId` (number) — target a specific worker during dispatch attempts.
   * @returns {(boolean|Promise<any>)[]} Array with per-item results: `true|false` or `Promise` when awaiting responses.
   */
  stopThePressBatch(items, options) {
    const { recreate, fwdOptions } = this._normalizeStopThePressOptions(options);
    this._resetPoolForStopThePress({ recreate, scope: 'stopThePressBatch' });

    try {
      return this.postMessageBatch(items, fwdOptions);
    } catch (err) {
      try {
        this._logger.error(err, 'stopThePressBatch: postMessageBatch failed');
      } catch (e) {
        this._debugLog?.(e, 'stopThePressBatch: logger.error failed');
      }
      // return an array of `false` to indicate none dispatched
      try {
        return new Array(items ? items.length : 0).fill(false);
      } catch (e) {
        return [];
      }
    }
  }

  /**
   * Add one worker to the pool immediately.
   * @returns {WorkerObj} The newly created worker entry.
   */
  addWorker() {
    if (this._terminated) {
      this._debugLog?.(null, 'addWorker: pool terminated, ignoring');
      return null;
    }
    let created;
    try {
      created = this._addWorkerInstance();
    } catch (err) {
      try {
        this._logger.error(err, 'addWorker: failed');
      } catch (e) {
        this._debugLog?.(e, 'addWorker: logger.error failed');
      }
      try {
        this._bus.emit('pool:error', { phase: 'addWorker', error: err });
      } catch (e) {
        this._debugLog?.(e, 'addWorker: bus.emit failed');
      }
      return null;
    }
    // A new worker changes the idle/busy verdict (a previously idle pool that
    // had its last worker removed must be re-evaluated for `drain()`).
    if (created) this._updateIdleState();
    return created;
  }

  /**
   * Remove the last worker from the pool and terminate it.
   * @returns {void}
   */
  removeWorker() {
    const w = this.workers.pop();
    if (!w) return;
    this._terminateWorker(w, 'removeWorker');
    // Terminating the last busy worker can make the pool idle.
    this._updateIdleState();
  }

  /**
   * Internal: terminate workers that have been idle longer than `idleTimeout`.
   * Keeps at least `minSize` workers alive.
   *
   * This routine scans workers from newest to oldest and terminates those
   * which have had no tasks for longer than `idleTimeout`, updating
   * termination statistics used by `getStats()`.
   *
   * @private
   * @returns {void}
   */
  _reapIdleWorkers() {
    if (this.idleTimeout <= 0) return;
    const now = nowMs();
    // keep at least minSize workers
    const reaped = [];
    for (let i = this.workers.length - 1; i >= 0; i--) {
      const w = this.workers[i];
      if (this.workers.length <= this.minSize) break;
      if (w.tasks === 0 && now - (w.lastActive || 0) > this.idleTimeout) {
        const id = this._terminateWorker(w, 'idle-reap');
        if (id != null) reaped.push(id);
        // Remove the worker without O(n) splice by swapping with the last
        // element and popping. This keeps removal O(1) and avoids shifting
        // the remaining array entries.
        const lastIndex = this.workers.length - 1;
        if (i === lastIndex) {
          this.workers.pop();
        } else {
          // Move last into position i and pop the tail.
          this.workers[i] = this.workers.pop();
        }
      }
    }
    // Report reaps on the same channel as every other scaling action, so
    // observers do not have to poll `getStats()` to notice idle shrinkage.
    if (reaped.length) {
      try {
        this._bus.emit('pool:scale', {
          action: 'remove',
          reason: 'idle-reap',
          terminated: reaped,
          count: reaped.length,
        });
      } catch (e) {
        this._debugLog?.(e, '_reapIdleWorkers: bus.emit failed');
      }
    }
    // re-evaluate idle state after pruning
    this._updateIdleState();
  }

  /**
   * Update the adaptive concurrency limit for this tick.
   *
   * The limit is a float in `[limitMin, limitMax]`, smoothed with
   * `smoothedLimit` below. These are the concurrency-control algorithms from
   * Netflix's `concurrency-limits`, which ports TCP congestion control to a
   * request concurrency window. The pool already tracks exactly the signals
   * they need, so this replaces guesswork with a feedback loop.
   *
   * - `aimd` — additive increase while healthy, multiplicative decrease on a
   *   congestion signal. Simplest and most robust.
   * - `vegas` — estimates the bottleneck queue as
   *   `limit * (1 - minRtt / currentRtt)`, increasing by `alpha` when that is
   *   below a threshold and decreasing by `beta` when above it. The reference
   *   implementation uses `alpha = 3*log10(limit)` and `beta = 6*log10(limit)`.
   * - `gradient2` — the divergence between a long- and a short-window RTT EWMA,
   *   `gradient = clamp(longRtt / currentRtt, 0.5, 1)`, then
   *   `limit = gradient * limit + queueSize`, smoothed. Unlike Vegas it does
   *   not use the window *minimum* latency, which biases the estimate.
   *
   * `ewma` (the default) does nothing here: it keeps the original
   * target-latency-threshold behaviour in `_autoScaleTick` unchanged.
   *
   * **The signal is end-to-end task latency, and Netflix's is queueing delay.**
   * That is the same quantity only for a uniform workload. For a pool whose
   * tasks vary in cost, `vegas`' `minRtt / currentRtt` and `aimd`'s
   * `shortRtt / longRtt` test conflate "queueing appeared" with "a heavier task
   * ran", and the controller will cut concurrency for work that was simply
   * expensive. Measured against a fixed limit this is untested either way —
   * `bench/claims.js` has no mode for it.
   *
   * **The `aimd` policy here is delay-shaped, despite the name.** Netflix's
   * `AIMDLimit` is loss-based; this branches on RTT divergence, the same shape
   * as `gradient2`. The loss-based AIMD in this library is
   * `PowerBackpressure._aimdStep`. See ADR 0005 for the full signal taxonomy.
   *
   * @returns {number} The updated limit.
   * @private
   */
  /**
   * How many workers this tick's scale action should move, given how far
   * latency currently sits from `targetMs`.
   *
   * **The thresholds in `_autoScaleTick` still decide the direction.** This only
   * sets the magnitude, inside the caller's existing `stepUp` / `stepDown`
   * ceiling — which is why nothing changes at the default `stepUp: 1`: a ceiling
   * of one worker is one worker, whatever the controller says.
   *
   * Before this, the step was a fixed count. A pool that was 20 % over target
   * added as many workers as one that was 300 % over, so the badly-over case
   * converged no faster than the marginal one. A PI controller on the relative
   * error scales the step by how far off the setpoint actually is, and its
   * integral term is what removes the residual: this is a *discrete* stepper, so
   * proportional action alone leaves a standing offset, which is exactly the
   * property `PowerServo`'s "converges to a setpoint a fixed gain cannot" test
   * pins.
   *
   * Normalised, not absolute: `measured` is `ewma / targetMs` against a setpoint
   * of `1`, so the gains are dimensionless and do not have to be retuned when
   * `targetMs` changes. Only `|output|` is used — the sign is already settled by
   * the hysteresis band and the queue-pressure check.
   *
   * `PowerServo` owns no timer, so `dt` is passed in; the tick's own
   * `intervalMs` is the right unit because that is the interval this runs on.
   *
   * @param {number} ewma - Current latency EWMA in ms.
   * @param {number} targetMs - Configured target.
   * @param {number} ceiling - `stepUp` or `stepDown`; the caller's hard limit.
   * @param {number} dtSeconds - Tick interval in seconds, for the integral.
   * @returns {number} A worker count in `[1, ceiling]`.
   */
  _autoscaleSteps(ewma, targetMs, ceiling, dtSeconds) {
    if (!(ceiling > 1) || ewma == null || !(targetMs > 0)) return Math.max(1, ceiling || 1);
    // **`min` is negative on purpose.** Only `|output|` is used, so the servo has
    // to be able to represent a negative command — and with `min: 0` the clamp
    // collapsed every overshoot to exactly 0 before the absolute value was taken,
    // so the step was permanently one worker and the controller did nothing at
    // all. That is the same class of bug as the anti-windup sign: the arithmetic
    // was right and the bound was on the wrong side of it.
    this._autoscaleServo ??= new PowerServo({
      setpoint: 1,
      kp: 1,
      ki: 0.25,
      min: -ceiling,
      max: ceiling,
    });
    // The servo holds no timer and no listener, so its dispose is a state reset;
    // recreating it when the ceiling shrinks keeps its integral inside the new
    // window rather than letting it unwind through a bound it no longer has.
    if (this._autoscaleServo.max !== ceiling) {
      this._autoscaleServo.max = ceiling;
      this._autoscaleServo.min = -ceiling;
      this._autoscaleServo.reset();
    }
    const relative = ewma / targetMs;
    const output = Math.abs(this._autoscaleServo.step(relative, dtSeconds));
    if (!Number.isFinite(output)) return 1;
    return Math.max(1, Math.min(ceiling, Math.round(output)));
  }

  _updateAdaptiveLimit() {
    const cfg = this._autoScale;
    if (!cfg || cfg.policy === 'ewma') return this._adaptiveLimit;

    const min = cfg.limitMin;
    const max = cfg.limitMax;
    const shortRtt = this._ewmaLatency;
    const longRtt = this._longEwmaLatency;
    const queueSize = this.queue.length;
    const current = this._adaptiveLimit;

    // Without any latency sample there is nothing to steer on. Seed the limit
    // at the current worker count so the controller starts from reality.
    if (shortRtt == null) return current;

    let next = current;
    switch (cfg.policy) {
      case 'aimd': {
        // Congestion = short RTT has risen meaningfully above the long RTT,
        // which means the extra concurrency is buying queueing, not throughput.
        const congested = longRtt != null && shortRtt > longRtt * 1.25;
        this._congestion = congested;
        next = congested ? current * cfg.aimdBeta : current + 1;
        break;
      }
      case 'vegas': {
        const minRtt = this._minLatencyWindow;
        // A minimum RTT estimate is required; without one the queue estimate
        // is meaningless, so grow cautiously instead of dividing by zero.
        if (!Number.isFinite(minRtt) || minRtt <= 0) {
          next = current + 1;
          break;
        }
        const alpha = 3 * Math.log10(Math.max(2, current));
        const beta = 6 * Math.log10(Math.max(2, current));
        const diff = current * (1 - minRtt / Math.max(shortRtt, minRtt));
        if (diff < alpha) {
          this._congestion = false;
          next = current + alpha;
        } else if (diff > beta) {
          this._congestion = true;
          next = current - beta;
        } else {
          this._congestion = false;
        }
        break;
      }
      case 'gradient2': {
        if (longRtt == null || longRtt <= 0) {
          next = current + 1;
          break;
        }
        const gradient = Math.max(0.5, Math.min(1, longRtt / shortRtt));
        // queueSize term: work still waiting is evidence the limit is too low.
        next = gradient * current + queueSize;
        this._congestion = gradient < 1;
        break;
      }
      default:
        return current;
    }

    if (!Number.isFinite(next)) return current;
    // Smooth so a single noisy tick cannot swing the fleet.
    const smoothed = current * 0.8 + Math.max(min, Math.min(max, next)) * 0.2;
    this._adaptiveLimit = Math.max(min, Math.min(max, smoothed));
    this._lastAdaptiveLimit = current;
    return this._adaptiveLimit;
  }

  /**
   * Autoscale tick: simple policy that grows/shrinks by one worker based on
   * pool-level EWMA latency and queue pressure. Runs only when `autoScale`
   * is configured on the pool.
   *
   * - scale up: when EWMA > targetMs OR queue length exceeds worker count
   * - scale down: when EWMA < targetMs * 0.5 AND queue is empty
   * @private
   */
  _autoScaleTick() {
    try {
      if (this._terminated || !this._autoScale || !this._autoScale.enabled) return;
      const now = nowMs();
      const cfg = this._autoScale;

      // reset backoff multiplier if enough time has passed since last scale
      if (
        this._lastAutoScaleAt &&
        cfg.backoffResetMs &&
        now - this._lastAutoScaleAt > cfg.backoffResetMs
      ) {
        this._autoScaleBackoffMultiplier = 1;
        // Declared here rather than only at its `??=` in `_autoscaleSteps`: a field
        // TS cannot see is a field it reports as absent, which cost 8 `TS2551`s the
        // first time round. The same lesson as `PowerServo._setpoint`, and the same
        // fix — and the same reminder that `??=` is invisible to a checkJs project.
        /** @type {PowerServo|null} */
        this._autoscaleServo = null;
      }

      // enforce effective cooldown between scale actions (taking backoff into account)
      const effectiveCooldown = Math.floor(
        (cfg.cooldownMs || 0) * (this._autoScaleBackoffMultiplier || 1)
      );
      if (this._lastAutoScaleAt && now - this._lastAutoScaleAt < effectiveCooldown) return;

      // Feedback loop: let the configured controller move the concurrency
      // limit before the step logic below reads it. Returns unchanged for the
      // default 'ewma' policy, which keeps the original behaviour intact.
      this._updateAdaptiveLimit();

      const target = cfg.targetMs;
      const hysteresis = cfg.hysteresis || 0.2;
      const ewma = this._ewmaLatency;
      const workers = this.workers.length;

      // scale-up heuristics: require EWMA to exceed target by hysteresis
      const upThreshold = target * (1 + hysteresis);
      const needScaleUp = ewma != null ? ewma > upThreshold : false;
      const queuePressure = this.queue.length > Math.ceil(workers * (1 + hysteresis));
      if (needScaleUp || queuePressure) {
        this._lastAutoScaleReason =
          needScaleUp && queuePressure ? 'latency+queue' : needScaleUp ? 'latency' : 'queue';
        if (workers < this.maxSize) {
          try {
            const stepCeiling = cfg.stepUp || 1;
            const steps = this._autoscaleSteps(ewma, target, stepCeiling, cfg.intervalMs / 1000);
            const maxAdd = Math.min(this.maxSize - workers, steps);
            let added = 0;
            let addFailed = false;
            for (let i = 0; i < maxAdd; i++) {
              try {
                const before = this.workers.length;
                this._addWorkerInstance();
                if (this.workers.length === before) break;
                added++;
              } catch (e) {
                addFailed = true;
                this._debugLog?.(e, 'autoScale: addWorker failed');
                try {
                  this._bus.emit('pool:error', { phase: 'autoScale:add', error: e });
                } catch (ee) {
                  this._debugLog?.(ee, 'autoScale: bus.emit failed');
                }
                break;
              }
            }
            this._lastAutoScaleOutcome = added > 0 ? 'added' : addFailed ? 'failed' : 'no-op';
            if (added > 0) {
              this._lastAutoScaleAt = now;
              // increase backoff multiplier for successive rapid scales
              // Cap the backoff multiplier to avoid unbounded growth.
              this._autoScaleBackoffMultiplier = Math.min(
                (this._autoScaleBackoffMultiplier || 1) * (cfg.backoffFactor || 1),
                cfg.backoffMaxMultiplier || 8
              );
            }
          } catch (e) {
            this._lastAutoScaleOutcome = 'failed';
            this._debugLog?.(e, 'autoScale: addWorker failed outer');
          }
        } else {
          this._lastAutoScaleOutcome = 'blocked';
        }
        return;
      }

      // scale-down heuristics: require EWMA to be below target by hysteresis
      const downThreshold = target * Math.max(0, 1 - hysteresis);
      const needScaleDown = ewma != null ? ewma < downThreshold : false;
      // The step servo is state like the backoff multiplier is, and it is dropped
      // when the pool is **quiet** — meaning this tick decided to do nothing. Not
      // when the cooldown expired: an earlier version reset on
      // `now - lastAutoScaleAt > cooldownMs`, which is the exact complement of the
      // cooldown guard above, so it fired on every tick that guard let through and
      // the integral could never survive a single interval.
      if (!needScaleUp && !queuePressure && !needScaleDown && this._autoscaleServo) {
        this._autoscaleServo.reset();
      }
      if (needScaleDown && this.queue.length === 0) {
        this._lastAutoScaleReason = 'latency';
        if (workers > this.minSize) {
          try {
            const stepCeilingDown = cfg.stepDown || 1;
            const stepsDown = this._autoscaleSteps(
              ewma,
              target,
              stepCeilingDown,
              cfg.intervalMs / 1000
            );
            const maxRemove = Math.min(workers - this.minSize, stepsDown);
            let removed = 0;
            // Prefer removing idle workers only (tasks === 0). Iterate from newest to oldest.
            for (let idx = this.workers.length - 1; idx >= 0 && removed < maxRemove; idx--) {
              const candidate = this.workers[idx];
              if (!candidate) continue;
              // skip busy workers to avoid losing in-flight tasks
              if (candidate.tasks > 0) continue;
              this._terminateWorker(candidate, 'autoscale');
              // remove candidate by swapping with last element and popping
              const lastIndex = this.workers.length - 1;
              if (idx === lastIndex) {
                this.workers.pop();
              } else {
                this.workers[idx] = this.workers.pop();
              }
              removed++;
            }
            // Only record a scale action when we actually removed workers.
            if (removed > 0) {
              this._lastAutoScaleOutcome = 'removed';
              this._lastAutoScaleAt = now;
              // Cap the backoff multiplier to avoid unbounded growth.
              this._autoScaleBackoffMultiplier = Math.min(
                (this._autoScaleBackoffMultiplier || 1) * (cfg.backoffFactor || 1),
                cfg.backoffMaxMultiplier || 8
              );
            } else {
              this._lastAutoScaleOutcome = 'blocked';
            }
          } catch (e) {
            this._lastAutoScaleOutcome = 'failed';
            this._debugLog?.(e, 'autoScale: remove worker failed');
          }
        } else {
          this._lastAutoScaleOutcome = 'blocked';
        }
      }
    } catch (e) {
      this._debugLog?.(e, 'autoScaleTick outer');
    }
  }

  /**
   * Emit the pool-idle synthetic message to `onmessage` and listeners.
   *
   * The emitted event object is
   * `{ data: { type: 'pool:idle', workers, stats } }`, where:
   *
   * - `data.workers` is the per-worker snapshot the pool is actually idle *by*:
   *   an array of `{ id, tasks, lastActive }`. A worker with `tasks !== 0` here
   *   means `_activeTasks` has drifted from the per-worker counts.
   * - `data.stats` is the aggregate `getStats()` summary (`queueLength`,
   *   `activeTasks`, `performance`, ...).
   *
   * Both are computed lazily and both used to be called "stats". The payload
   * was always the `getStats()` *summary* while the JSDoc described an
   * *array*, so a listener written against the documentation did
   * `ev.data.stats.map(w => w.id)` and got a `TypeError` on a busy pool - the
   * per-worker array simply was not reachable. Naming them for what they are is
   * the fix; the summary keeps the `stats` key so existing readers of
   * `ev.data.stats` are unaffected.
   *
   * Emission semantics:
   * - The event is emitted only when the pool transitions from non-idle to idle
   *   (i.e. the task queue is empty and every worker has `tasks === 0`).
   * - The synthetic event is delivered to `pool.onmessage`, any `'message'` listeners,
   *   as well as to `pool.onidle` and `addEventListener('idle', cb)` listeners.
   * - The event `data.type` is `'pool:idle'` and can be used to distinguish it
   *   from normal worker messages.
   *
   * @private
   * @returns {void}
   */
  /**
   * Build the idle event object. Both payloads are computed lazily (via
   * getters) so the `getStats()` allocation (which maps over all workers) is
   * skipped on idle transitions when no listener actually reads them.
   * @private
   * @returns {{data:{type:string,workers:{id:number,tasks:number,lastActive:number}[],stats:object}}}
   */
  _buildIdleEvent() {
    const self = this;
    /** @type {object|undefined} */
    let stats;
    let statsComputed = false;
    /** @type {{id:number,tasks:number,lastActive:number}[]|undefined} */
    let workers;
    let workersComputed = false;
    return {
      data: {
        type: 'pool:idle',
        get workers() {
          if (!workersComputed) {
            workers = self.workers.map((w) => ({
              id: w.id,
              tasks: w.tasks,
              lastActive: w.lastActive,
            }));
            workersComputed = true;
          }
          return workers;
        },
        get stats() {
          if (!statsComputed) {
            stats = self.getStats();
            statsComputed = true;
          }
          return stats;
        },
      },
    };
  }

  _emitIdle() {
    const ev = this._buildIdleEvent();
    this._isIdle = true;
    if (this._onmessage) {
      try {
        this._onmessage(ev);
      } catch (err) {
        this._logger.error(err, 'Pool onmessage handler error');
      }
    }
    if (this._onidle) {
      try {
        this._onidle(ev);
      } catch (err) {
        this._logger.error(err, 'Pool onidle handler error');
      }
    }
    try {
      this._bus.emit('message', ev);
    } catch (err) {
      this._logger.error(err, 'pool listener error');
    }
    try {
      this._bus.emit('idle', ev);
    } catch (err) {
      this._logger.error(err, 'pool idle listener error');
    }
  }

  /**
   * Check current state and emit idle event if transitioning to idle.
   *
   * This function examines active task counts and queue length to detect a
   * transition from non-idle to idle and will call `_emitIdle()` exactly once
   * on such transitions.
   *
   * @private
   * @returns {void}
   */
  _updateIdleState() {
    const queueEmpty = this.queue.length === 0;
    const allWorkersIdle = this._activeTasks === 0;
    const allIdle = allWorkersIdle && queueEmpty;

    if (allIdle && !this._isIdle) {
      // emit idle notification
      this._emitIdle();
    } else if (!allIdle && this._isIdle) {
      // mark non-idle
      this._isIdle = false;
    }
  }

  /**
   * Terminate the entire pool, clear queue and the reaper interval.
   */
  terminate() {
    // Delegate to shutdown to ensure timers cleared and pending Promises rejected
    try {
      this.shutdown();
    } catch (e) {
      // best-effort: swallow to preserve original terminate() semantics
    }
  }

  /**
   * Synchronous disposal hook (TC39 Explicit Resource Management).
   * Allows `using`-style disposal when supported: `pool[Symbol.dispose]()`.
   * Must be synchronous (returns `undefined`) so `using` blocks don't await
   * and leak in-flight work; it performs a hard stop via `shutdown()`.
   */

  /**
   * Named alias for the `Symbol.dispose` implementation, so callers who do not
   * want to reach for the symbol still have something to call.
   * @returns {void}
   */
  dispose() {
    detach(this._metrics);
    this._metrics = null;
    this[Symbol.dispose]();
  }

  [Symbol.dispose]() {
    this.shutdown();
  }

  /**
   * Asynchronous disposal hook. Drains outstanding work and then terminates.
   * Use `await pool[Symbol.asyncDispose]()` in environments that support it.
   */
  async [Symbol.asyncDispose]() {
    try {
      await this.drain();
    } catch (err) {
      // ignore drain failures and proceed to terminate
    }
    this.terminate();
  }

  /**
   * Return stats for debugging and telemetry.
   * @returns {{status:{id:number,tasks:number,lastActive:number}[],performance:Object,queueLength:number,queueDepth:number,queuePressure:number,activeTasks:number,workerCount:number,minSize:number,maxSize:number,isIdle:boolean}}
   */
  getStats() {
    const status = this.workers.map((w) => ({
      id: w.id,
      tasks: w.tasks,
      lastActive: w.lastActive,
    }));

    // Negotiation state, per worker, so an operator can see whether the pool has
    // actually upgraded — and a mixed fleet is the normal state during a
    // rollout, so the counts are the useful part: "2 of 9 on native" is the
    // answer to "is negotiation on", and `messageCodec` alone cannot give it.
    const negotiated = this.workers.filter((w) => w.protocol?.native).length;
    const protocol = {
      mode: this._messageCodec,
      nativeAvailable: this._nativeCloneAvailable,
      nativeWorkers: negotiated,
      workers: this.workers.map((w) => ({ id: w.id, codecs: w.protocol?.codecs ?? ['json'] })),
    };

    const now = nowMs();
    const liveDuration = this._createdAt != null ? Math.max(0, now - this._createdAt) : 0;
    const totalWorkersCreated = this._totalWorkersCreated || this.workers.length;
    const totalTasksPerformed = this._totalTasksCompleted || 0;

    // average number of tasks per worker until termination.
    // Include terminated workers (historical) and currently-alive workers
    // so the metric reflects work-per-worker across the pool lifetime.
    const terminatedCount = this._terminatedWorkerTaskCountsCount || 0;
    const terminatedTotal = this._terminatedWorkerTaskCountsTotal || 0;
    // sum completed tasks for currently alive workers
    let aliveCompletedTotal = 0;
    for (const w of this.workers) aliveCompletedTotal += w.completedTasks || 0;
    const aliveCount = this.workers.length || 0;
    const combinedCount = terminatedCount + aliveCount;
    const avgTasksPerWorkerUntilTermination =
      combinedCount > 0 ? (terminatedTotal + aliveCompletedTotal) / combinedCount : 0;

    // time-per-task statistics (Welford streaming stats provide O(1) memory)
    let min = 0,
      max = 0,
      average = 0,
      stddev = 0,
      percentSlowTasks = 0;
    const count = this._taskDurationsWelfordCount || 0;
    if (count > 0) {
      min = this._taskDurationsMin === Number.POSITIVE_INFINITY ? 0 : this._taskDurationsMin;
      max = this._taskDurationsMax === Number.NEGATIVE_INFINITY ? 0 : this._taskDurationsMax;
      average = this._taskDurationsWelfordMean;
      const variance = count > 1 ? this._taskDurationsWelfordM2 / count : 0;
      stddev = Math.sqrt(variance);
      // Exact, O(1) percentage of completed tasks whose duration exceeded
      // `slowTaskThreshold`. Stays 0 when the threshold is disabled (Infinity).
      percentSlowTasks = count > 0 ? ((this._slowTaskCount || 0) / count) * 100 : 0;
    }
    const queueWaitCount = this._queueWaitWelfordCount || 0;
    const queueWaitVariance = queueWaitCount > 1 ? this._queueWaitWelfordM2 / queueWaitCount : 0;
    const queueWait = {
      count: queueWaitCount,
      min: queueWaitCount > 0 ? this._queueWaitMin : 0,
      max: queueWaitCount > 0 ? this._queueWaitMax : 0,
      average: queueWaitCount > 0 ? this._queueWaitWelfordMean : 0,
      stddev: Math.sqrt(queueWaitVariance),
    };

    return {
      status,
      protocol,
      performance: {
        poolLiveDuration: liveDuration,
        totalWorkersCreated,
        totalTasksPerformed,
        averageTasksPerWorkerUntilTermination: avgTasksPerWorkerUntilTermination,
        timePerTask: { max, min, average, stddev },
        queueWait,
        percentSlowTasks,
        // Adaptive concurrency controller.
        //
        // **`autoScalePolicy` is gated on the interval, not on the config object.**
        // `_clearLifecycleIntervals()` nulls `_autoScaleInterval` but leaves
        // `_autoScale` in place, because the policy and its bounds are still the
        // pool's configuration and `recreateWorkers: true` must be able to start
        // the controller again from them. Reporting the config therefore described
        // a controller that **can never tick**: verified after
        // `stopThePress(..., { recreateWorkers: false })`, which reported
        // `autoScalePolicy: 'aimd'` with `_autoScaleInterval` null. An operator
        // reading that would conclude adaptation was running. `null` means "no
        // controller is ticking", which is the only question this field can answer
        // honestly.
        //
        // `concurrencyLimit` is deliberately **not** gated the same way, and the
        // difference is deliberate: it reports `_adaptiveLimit`, a stored number
        // that keeps its value when the controller stops, so it stays true. The
        // policy was a live claim and this is a retained one.
        concurrencyLimit:
          this._autoScale && this._autoScale.policy !== 'ewma'
            ? Math.round(this._adaptiveLimit * 100) / 100
            : null,
        autoScalePolicy: this._autoScale && this._autoScaleInterval ? this._autoScale.policy : null,
        congestion: this._autoScale ? Boolean(this._congestion) : null,
        lastScaleReason: this._autoScale ? this._lastAutoScaleReason : null,
        lastScaleOutcome: this._autoScale ? this._lastAutoScaleOutcome : null,
        // **Whether the idle reaper is actually running.** The reaper had no field
        // at all, which is how POOL-007's second half stayed invisible: the
        // interval is cleared by `stopThePress(..., { recreateWorkers: false })`
        // and by `shutdown()`, and neither is restorable, so a pool can silently
        // accumulate idle workers past `idleTimeout` for the rest of its life with
        // nothing in `getStats()` to say so.
        //
        // **A plain boolean, deliberately.** An earlier draft of this comment
        // claimed a tri-state — `null` for "never configured" against `false` for
        // "configured and stopped" — which the code does not have and cannot have:
        // the reaper is created unconditionally in the constructor, so there is no
        // pool with no reaper, only pools whose reaper is stopped. A comment
        // describing a state the value never takes is worse than none, and a
        // reader branching on `=== null` would silently never match. `false` means
        // "not running", full stop; `test/powerPool.lifecycleState.test.js` asserts
        // the type so the value cannot drift into a tri-state later either.
        idleReapingActive: this._reaperInterval !== null && this._reaperInterval !== undefined,
      },
      // Silent batch drops were invisible; this makes them countable.
      postFailures: this._postFailures,
      // POOL-013. The cost is `lookups`, and it must read as zero on a pool that
      // never opted in — that is the number the row asks for and the one an
      // operator checking "what did this cost me" needs first. `size` is the live
      // ledger; a ledger that only ever grows is a leak, so `expired` says whether
      // the TTL is actually reclaiming it.
      idempotency: {
        enabled: this._idempotency !== null,
        ttlMs: this._idempotencyTtlMs,
        lookups: this._idempotencyLookups,
        duplicatesInFlight: this._idempotencyDuplicatesInFlight,
        duplicatesSettled: this._idempotencyDuplicatesSettled,
        expired: this._idempotencyExpired,
        size: this._idempotencySize,
      },
      queueLength: this.queue.length,
      queueDepth: this.queue.length,
      queuePressure: Number.isFinite(this._maxQueueLength)
        ? Math.min(1, this.queue.length / Math.max(1, this._maxQueueLength))
        : this.queue.length > 0
          ? 1
          : 0,
      activeTasks: this._activeTasks,
      workerCount: this.workers.length,
      minSize: this.minSize,
      maxSize: this.maxSize,
      isIdle: this._activeTasks === 0 && this.queue.length === 0,
    };
  }

  /**
   * Return a Promise that resolves when the pool becomes idle (queue empty and all workers have tasks === 0).
   * Resolves with the result of `getStats()` at the time of idle.
   *
   * The wait is bounded three ways, and every one of them **abandons the wait,
   * never the work** - the pool keeps dispatching and keeps serving every other
   * caller. That is the contract `drain()` has always had; what is new is that
   * the wait can actually be given up on without leaking anything:
   *
   * - `signal` - an `AbortSignal` rejects with its reason. `AbortError` unless
   *   the caller aborted with their own `Error`.
   * - `timeout` - rejects with `ERR_POOL_DRAIN_TIMEOUT` after `timeout` ms.
   *   Without it a drain against a wedged worker waits forever, which is
   *   indistinguishable from a hang.
   * - `maxDrainWaiters` (constructor option) - rejects with
   *   `ERR_POOL_DRAIN_TOO_MANY_WAITERS` once too many are already waiting.
   *
   * Previously only `signal` existed, and it leaked: `raceWithAbort` rejected
   * the returned promise but left the `idle` listener attached, so an aborted
   * drain retained a closure and a listener slot until the pool happened to go
   * idle again. This implementation owns the listener lifecycle directly and
   * detaches on *every* exit path.
   *
   * @param {object} [options]
   * @param {AbortSignal} [options.signal] - Abandons the wait when aborted.
   * @param {number} [options.timeout] - Abandons the wait after this many ms.
   * @returns {Promise<object>} Promise resolving to `getStats()`.
   */
  drain(options = {}) {
    const signal = options?.signal ?? null;
    const rawTimeout = Number(options?.timeout);
    // A non-finite or non-positive `timeout` means "no timeout", matching every
    // other timeout option in the library.
    const timeout = Number.isFinite(rawTimeout) && rawTimeout > 0 ? Math.floor(rawTimeout) : 0;

    const queueEmpty = this.queue.length === 0;
    const allWorkersIdle = this._activeTasks === 0;
    const allIdle = allWorkersIdle && queueEmpty;

    if (allIdle) {
      return signal?.aborted
        ? Promise.reject(abortReason(signal))
        : Promise.resolve(this.getStats());
    }
    if (signal?.aborted) return Promise.reject(abortReason(signal));

    if (this._drainWaiters >= this._maxDrainWaiters) {
      return Promise.reject(
        poolRefusal(
          'ERR_POOL_DRAIN_TOO_MANY_WAITERS',
          `drain(): ${this._drainWaiters} drain(s) already waiting (maxDrainWaiters ${this._maxDrainWaiters})`
        )
      );
    }

    this._drainWaiters++;
    return new Promise((resolve, reject) => {
      /** @type {any} */
      let timer = null;
      let done = false;

      /**
       * Release the listener, the timer and the waiter slot exactly once,
       * whichever path got here first.
       * @returns {void}
       */
      const release = () => {
        if (done) return;
        done = true;
        if (timer) {
          clearTimeout(timer);
          timer = null;
        }
        this._drainWaiters--;
        try {
          this.removeEventListener('idle', onIdle);
        } catch (e) {
          this._debugLog?.(e, 'drain: removeEventListener failed');
        }
      };

      const onIdle = () => {
        release();
        resolve(this.getStats());
      };
      const onAbort = () => {
        release();
        // Only ever registered when `signal` is non-null, further down.
        reject(abortReason(/** @type {AbortSignal} */ (signal)));
      };
      const onTimeout = () => {
        release();
        reject(
          poolRefusal(
            'ERR_POOL_DRAIN_TIMEOUT',
            `drain(): pool did not become idle within ${timeout}ms`
          )
        );
      };

      if (timeout) {
        // Deliberately *not* `setSafeTimeout`. An unref'd timer would let a
        // Node process exit while a caller is `await pool.drain({ timeout })`,
        // which is the one case where holding the loop open is the point.
        timer = setTimeout(onTimeout, timeout);
      }
      if (signal) signal.addEventListener('abort', onAbort, { once: true });
      this.addEventListener('idle', onIdle);
    });
  }

  /**
   * Add an event listener for pool events. Supported types: 'message', 'error', 'messageerror', 'idle'.
   * @param {'message'|'error'|'messageerror'|'idle'} type
   * @param {Function} cb
   */
  addEventListener(type, cb) {
    // Supported types: message, error, messageerror, idle, resize
    if (typeof cb !== 'function') return;
    this._bus.on(type, cb);
    // If registering an 'idle' listener while the pool is actually idle,
    // invoke it immediately. Use the same logic as `_updateIdleState`.
    if (type === 'idle') {
      const queueEmpty = this.queue.length === 0;
      const allWorkersIdle = this._activeTasks === 0;
      if (allWorkersIdle && queueEmpty) {
        const ev = this._buildIdleEvent();
        try {
          cb(ev);
        } catch (err) {
          this._logger.error(err, 'pool idle listener error');
        }
      }
    }
  }

  /**
   * Remove a previously added event listener.
   * @param {'message'|'error'|'messageerror'|'idle'} type
   * @param {Function} cb
   */
  removeEventListener(type, cb) {
    if (!cb || typeof cb !== 'function') return;
    this._bus.off(type, cb);
  }

  /**
   * onresize handler called when the pool is resized and workers are terminated/added.
   * Receives an event object: `{ data: { type: 'pool:resize', terminated: Array<number>, added: number, minSize, maxSize } }`
   * @type {Function|null}
   */
  get onresize() {
    return this._onresize;
  }
  set onresize(cb) {
    this._onresize = cb;
  }

  /**
   * onmessage handler called when any worker posts a message.
   * @type {Function|null}
   */
  get onmessage() {
    return this._onmessage;
  }
  set onmessage(cb) {
    this._onmessage = cb;
  }

  /**
   * onerror handler called when a worker emits an error.
   * @type {Function|null}
   */
  get onerror() {
    return this._onerror;
  }
  set onerror(cb) {
    this._onerror = cb;
  }

  /**
   * onidle handler called when the pool becomes idle.
   * @type {Function|null}
   */
  get onidle() {
    return this._onidle;
  }
  set onidle(cb) {
    this._onidle = cb;
    if (typeof cb === 'function') {
      const queueEmpty = this.queue.length === 0;
      const allWorkersIdle = this._activeTasks === 0;
      if (allWorkersIdle && queueEmpty) {
        const ev = this._buildIdleEvent();
        try {
          cb(ev);
        } catch (err) {
          this._logger.error(err, 'Pool onidle handler error');
        }
      }
    }
  }

  /**
   * Pause dequeueing from the internal task queue.
   * Queued tasks remain in the queue until `resumeQueue()` is called.
   * This is useful for controlled backpressure when downstream consumers
   * are temporarily unable to accept more work.
   */
  pauseQueue() {
    this._queuePaused = true;
  }

  /**
   * Resume dequeueing from the internal task queue and attempt to dispatch
   * waiting tasks to available workers.
   */
  resumeQueue() {
    if (!this._queuePaused) return;
    this._queuePaused = false;
    this._dispatchQueuedTasks();
  }

  /**
   * Alias for `pauseQueue()` to provide a simpler public API.
   */
  pause() {
    return this.pauseQueue();
  }

  /**
   * Alias for `resumeQueue()` to provide a simpler public API.
   */
  resume() {
    return this.resumeQueue();
  }

  /**
   * Whether queued dispatch is currently paused.
   * @returns {boolean}
   */
  get queuePaused() {
    return this._queuePaused;
  }

  /**
   * Dispatch queued tasks to available workers when the queue is not paused.
   * @private
   */
  _dispatchQueuedTasks() {
    if (this._queuePaused || !this.taskQueueEnabled || this.queue.length === 0) return;
    const queue = this.queue;
    const maxTasksPerWorker = this._maxTasksPerWorker;
    const adaptiveLimit =
      this._autoScale?.policy && this._autoScale.policy !== 'ewma'
        ? Math.max(1, Math.ceil(this._adaptiveLimit))
        : null;
    let adaptiveSlots =
      adaptiveLimit === null
        ? Number.POSITIVE_INFINITY
        : Math.max(0, adaptiveLimit - this._activeTasks);
    const now = nowMs();
    let dispatched = false;

    for (const workerObj of this.workers) {
      let remainingSlots = maxTasksPerWorker - workerObj.tasks;
      while (remainingSlots > 0 && adaptiveSlots > 0 && queue.length > 0) {
        const item = queue.shift();
        try {
          const dispatch = this._encodeForWorker(workerObj, item);
          this._dispatchToWorker(workerObj, dispatch, {
            correlationId: item.correlationId,
            startTime: now,
          });
          remainingSlots--;
          adaptiveSlots--;
          workerObj.lastActive = now;
          dispatched = true;
        } catch (err) {
          this._debugLog?.(err, 'dispatch queued message to worker failed');
          this._logger.error(err, 'Failed to dispatch queued message to worker');
          break;
        }
      }
    }

    if (this._queueHighCrossed && this.queue.length <= this._queueHighThreshold) {
      this._queueHighCrossed = false;
    }
    if (dispatched) this._updateIdleState();
  }
}
